'use strict';
(function executeClassicHomepageBundle(sources){
  const host=document.head||document.documentElement;
  for(const [asset,source] of sources){
    const script=document.createElement('script');
    script.dataset.kgBundleSource=asset;
    script.textContent=source;
    host.appendChild(script);
    script.remove();
  }
})([["src/37-subscription-plans.js","\"use strict\";\n\n/*\n * 学员订阅套餐与权益模型。\n *\n * 本文件只负责：套餐常量、套餐设置、价格/折扣派生、权益/用量文案。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionPlansModule = function(ctx={}){\n    const refresh = function(){\n      if(typeof ctx.decorateSubscriptionElements === \"function\") ctx.decorateSubscriptionElements();\n    };\n\n    const PLAN_ALIASES = {\n      free:\"free\",\n      free_student:\"free\",\n      trial:\"free\",\n      monthly:\"monthly\",\n      month:\"monthly\",\n      basic:\"monthly\",\n      basic_student:\"monthly\",\n      quarterly:\"quarterly\",\n      quarter:\"quarterly\",\n      quarter_year:\"quarterly\",\n      qtr:\"quarterly\",\n      season:\"quarterly\",\n      half_year:\"half_year\",\n      halfyear:\"half_year\",\n      half_yearly:\"half_year\",\n      halfyearly:\"half_year\",\n      half:\"half_year\",\n      pro:\"half_year\",\n      pro_student:\"half_year\",\n      lifetime:\"lifetime\",\n      life:\"lifetime\",\n      forever:\"lifetime\"\n    };\n\n    const PLAN_ORDER = [\"free\",\"monthly\",\"quarterly\",\"half_year\",\"lifetime\"];\n\n    const PLANS = {\n      free:{\n        id:\"free\",\n        enabled:true,\n        name:\"免费学员\",\n        shortName:\"免费\",\n        level:0,\n        billingCycle:\"free\",\n      durationDays:0,\n        paymentAmountFen:0,\n        priceText:\"¥0\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"长期有效\",\n        badgeText:\"体验\",\n        description:\"适合公开示例、轻量练习和体验核心流程。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          demoOnly:true,\n          allExamPapers:false\n        },\n        limits:{\n          dailyTraining:10,\n          recallMaps:1,\n          graphNodes:50,\n          recallNodes:30,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      monthly:{\n        id:\"monthly\",\n        enabled:true,\n        name:\"月度会员\",\n        shortName:\"月度\",\n        level:1,\n        billingCycle:\"monthly\",\n      durationDays:30,\n        paymentAmountFen:2900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"30 天\",\n        badgeText:\"灵活\",\n        description:\"适合短期备考、阶段性冲刺和低门槛体验完整学习能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      quarterly:{\n        id:\"quarterly\",\n        enabled:true,\n        name:\"季度会员\",\n        shortName:\"季度\",\n        level:2,\n        billingCycle:\"quarterly\",\n      durationDays:90,\n        paymentAmountFen:7900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"90 天\",\n        badgeText:\"进阶\",\n        description:\"适合一个阶段的系统备考，权益与半年会员保持一致，开放更完整的题库训练和深度回忆能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      half_year:{\n        id:\"half_year\",\n        enabled:true,\n        name:\"半年会员\",\n        shortName:\"半年\",\n        level:3,\n        billingCycle:\"half_year\",\n      durationDays:180,\n        paymentAmountFen:13900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"180 天\",\n        badgeText:\"推荐\",\n        recommended:true,\n        description:\"适合完整备考周期，开放更完整的题库训练和深度回忆能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      lifetime:{\n        id:\"lifetime\",\n        enabled:true,\n        name:\"终身会员\",\n        shortName:\"终身\",\n        level:4,\n        billingCycle:\"lifetime\",\n      durationDays:-1,\n        paymentAmountFen:39900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"永久有效\",\n        badgeText:\"终身\",\n        description:\"适合长期学习和深度用户，包含当前高级学习能力并预留后续高级功能。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true,\n          analytics:true,\n          futureAdvanced:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      }\n    };\n\n    const FEATURE_LABELS = {\n      basicTraining:\"基础刷题\",\n      basicRecall:\"基础深度回忆\",\n      personalGraph:\"个人知识图谱\",\n      demoOnly:\"公开示例体验\",\n      standardQuestionBank:\"标准题库训练\",\n      allExamPapers:\"全部已发布试卷\",\n      learningPackageImport:\"学习包导入\",\n      learningPackageExport:\"学习包导出\",\n      advancedRecall:\"高级深度回忆\",\n      analytics:\"学习分析\",\n      futureAdvanced:\"后续高级功能\"\n    };\n\n    const LIMIT_LABELS = {\n      dailyTraining:\"每日训练\",\n      recallMaps:\"回忆图谱\",\n      graphNodes:\"图谱卡牌\",\n      recallNodes:\"深度回忆知识点\",\n      importPackages:\"学习包导入\",\n      exportPackages:\"学习包导出\"\n    };\n\n    function normalizePlanId(planId){\n      const raw=String(planId || \"free\").trim();\n      const lower=raw.toLowerCase();\n      return PLAN_ALIASES[lower] || (PLANS[raw] ? raw : \"free\");\n    }\n    function basePlanById(planId){\n      return PLANS[normalizePlanId(planId)] || PLANS.free;\n    }\n    function normalizeDiscountPercent(value){\n      if(value == null || String(value).trim() === \"\") return \"\";\n      let n=Number(String(value).replace(\"%\",\"\").trim());\n      if(!Number.isFinite(n)) return \"\";\n      if(n > 0 && n <= 1) n=n*100;\n      n=Math.max(0,Math.min(100,n));\n      return Number.isInteger(n) ? String(n) : String(Number(n.toFixed(2)));\n    }\n    function normalizePaymentAmountFen(value){\n      const amount=Number(value);\n      return Number.isInteger(amount)&&amount>=0?amount:null;\n    }\n    function formatPaymentAmountFen(amountFen){\n      const amount=normalizePaymentAmountFen(amountFen);\n      if(amount===null)return \"\";\n      const yuan=amount/100;\n      return amount%100===0?`￥${yuan}`:`￥${yuan.toFixed(2)}`;\n    }\n    function splitPriceText(text){\n      const raw=String(text || \"\").trim();\n      const match=raw.match(/^([^0-9]*)([0-9]+(?:\\.[0-9]+)?)(.*)$/);\n      if(!match) return null;\n      return {prefix:match[1] || \"\", amount:Number(match[2]), decimals:(match[2].split(\".\")[1]||\"\").length, suffix:match[3] || \"\"};\n    }\n    function formatDiscountAmount(amount, decimals){\n      if(!Number.isFinite(amount)) return \"\";\n      const fixed=decimals > 0 ? amount.toFixed(Math.min(decimals,2)) : String(Math.round(amount));\n      return fixed.replace(/\\.0+$/,\"\").replace(/(\\.\\d*?)0+$/, \"$1\");\n    }\n    function deriveDiscountPrice(originalText, discountPercent){\n      const raw=String(originalText || \"\").trim();\n      if(!raw) return \"\";\n      const normalized=normalizeDiscountPercent(discountPercent);\n      if(normalized === \"\") return raw;\n      const info=splitPriceText(raw);\n      const pct=Number(normalized);\n      if(!info || !Number.isFinite(pct) || pct < 0) return raw;\n      const amount=info.amount * pct / 100;\n      return `${info.prefix}${formatDiscountAmount(amount,info.decimals)}${info.suffix}`;\n    }\n    function deriveDiscountLabel(discountPercent){\n      const pct=Number(normalizeDiscountPercent(discountPercent));\n      if(!Number.isFinite(pct) || pct <= 0 || pct >= 100) return \"\";\n      const off=100-pct;\n      return `-${Number.isInteger(off)?off:Number(off.toFixed(1))}%`;\n    }\n    function cleanPlanPatch(patch={}){\n      const out={};\n      if(Object.prototype.hasOwnProperty.call(patch,\"enabled\")) out.enabled=!!patch.enabled;\n      if(Object.prototype.hasOwnProperty.call(patch,\"recommended\")) out.recommended=!!patch.recommended;\n      [\"name\",\"shortName\",\"priceText\",\"originalPriceText\",\"durationText\",\"badgeText\",\"description\",\"benefitText\",\"usageText\"].forEach(key=>{\n        if(Object.prototype.hasOwnProperty.call(patch,key)) out[key]=String(patch[key] == null ? \"\" : patch[key]).trim();\n      });\n      if(Object.prototype.hasOwnProperty.call(patch,\"paymentAmountFen\")){\n        const amount=normalizePaymentAmountFen(patch.paymentAmountFen);\n        if(amount!==null)out.paymentAmountFen=amount;\n      }\n      if(Object.prototype.hasOwnProperty.call(patch,\"discountPercent\")) out.discountPercent=normalizeDiscountPercent(patch.discountPercent);\n      return out;\n    }\n    function readPlanSettings(){\n      // 套餐价格只认后端：remote 由 direct-system-adapter 启动时从 /api/v1/subscriptions/plans 预载。\n      // 不再读写 localStorage，避免本机缓存价与后台配置脱节。\n      const remote=window.KGSubscriptionRemotePlanSettings;\n      const out={};\n      if(remote && typeof remote === \"object\"){\n        PLAN_ORDER.forEach(id=>{\n          if(remote[id] && typeof remote[id] === \"object\") out[id]=cleanPlanPatch(remote[id]);\n        });\n      }\n      return out;\n    }\n    function savePlanSettings(settings){\n      const out={};\n      if(settings && typeof settings === \"object\"){\n        PLAN_ORDER.forEach(id=>{\n          if(settings[id] && typeof settings[id] === \"object\") out[id]=cleanPlanPatch(settings[id]);\n        });\n      }\n      window.KGSubscriptionRemotePlanSettings=Object.freeze(out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-plan-change\",{detail:{settings:out}}));\n      refresh();\n      return out;\n    }\n    function setPlanSettings(planId, patch={}){\n      const id=normalizePlanId(planId);\n      const settings=readPlanSettings();\n      settings[id]={...(settings[id]||{}),...cleanPlanPatch(patch)};\n      return savePlanSettings(settings)[id] || {};\n    }\n    function resetPlanSettings(planId){\n      const id=normalizePlanId(planId);\n      const settings=readPlanSettings();\n      delete settings[id];\n      savePlanSettings(settings);\n      return planById(id);\n    }\n    function planById(planId){\n      const base=basePlanById(planId);\n      const settings=readPlanSettings()[base.id] || {};\n      const merged={...base,...settings,id:base.id,level:base.level,billingCycle:base.billingCycle,durationDays:base.durationDays,features:{...base.features},limits:{...base.limits}};\n      const serverPrice=formatPaymentAmountFen(merged.paymentAmountFen);\n      const autoPrice=deriveDiscountPrice(merged.originalPriceText,merged.discountPercent);\n      const discountText=deriveDiscountLabel(merged.discountPercent);\n      return {...merged,priceText:serverPrice || autoPrice || merged.priceText,discountText};\n    }\n    function featureLabel(feature){\n      return FEATURE_LABELS[feature] || feature;\n    }\n    function splitLines(value){\n      return String(value || \"\")\n        .split(/\\r?\\n/)\n        .map(line=>line.trim())\n        .filter(Boolean);\n    }\n    function defaultPlanBenefitItems(plan){\n      return Object.entries(plan && plan.features || {})\n        .filter(([,on])=>!!on)\n        .map(([key])=>featureLabel(key));\n    }\n    function planBenefitItems(plan){\n      const lines=splitLines(plan && plan.benefitText);\n      return lines.length ? lines : defaultPlanBenefitItems(plan);\n    }\n    function defaultPlanUsageText(plan){\n      const limits=plan && plan.limits || {};\n      const keys=[\"dailyTraining\",\"recallMaps\",\"graphNodes\",\"recallNodes\"];\n      const parts=keys.filter(key=>Object.prototype.hasOwnProperty.call(limits,key)).map(key=>{\n        const value=limits[key];\n        const text=Number(value)===-1 ? \"不限\" : String(value);\n        return `${LIMIT_LABELS[key]||key}：${text}`;\n      });\n      if((plan && plan.features && (plan.features.learningPackageImport || plan.features.learningPackageExport)) || Object.prototype.hasOwnProperty.call(limits,\"importPackages\") || Object.prototype.hasOwnProperty.call(limits,\"exportPackages\")){\n        parts.push(\"学习包导入/导出：不限\");\n      }\n      return parts.join(\" · \" );\n    }\n    function planUsageText(plan){\n      const custom=String(plan && plan.usageText || \"\").trim();\n      return custom || defaultPlanUsageText(plan);\n    }\n    function planList(options={}){\n      const includeDisabled=!!options.includeDisabled;\n      return PLAN_ORDER.map(id=>planById(id)).filter(plan=>plan && (includeDisabled || plan.enabled !== false));\n    }\n    function enabledPlanList(){\n      return planList({includeDisabled:false});\n    }\n    function expiresAtForPlan(planId, startedAt=Date.now()){\n      const plan=planById(planId);\n      if(!plan || plan.durationDays <= 0) return 0;\n      return Number(startedAt || Date.now()) + plan.durationDays * 24 * 60 * 60 * 1000;\n    }\n\n    return {\n      PLAN_ALIASES,\n      PLAN_ORDER,\n      PLANS,\n      FEATURE_LABELS,\n      LIMIT_LABELS,\n      readPlanSettings,\n      savePlanSettings,\n      setPlanSettings,\n      resetPlanSettings,\n      normalizePlanId,\n      basePlanById,\n      planById,\n      planList,\n      enabledPlanList,\n      expiresAtForPlan,\n      deriveDiscountPrice,\n      deriveDiscountLabel,\n      formatPaymentAmountFen,\n      featureLabel,\n      planBenefitItems,\n      planUsageText,\n      defaultPlanBenefitItems,\n      defaultPlanUsageText\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-plans.js"],["src/37-subscription-orders.js","\"use strict\";\n\n/*\n * 学员订阅订单模块。\n *\n * 本文件只负责：订单申请、确认开通、取消、删除与订单状态文案。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionOrdersModule = function(ctx={}){\n    const ORDER_KEY = \"kg_student_subscription_orders_v1\";\n\n    const ORDER_STATUS_LABELS = {\n      pending:\"待确认\",\n      approved:\"已开通\",\n      cancelled:\"已取消\"\n    };\n\n    function orderStatusLabel(status){\n      return ORDER_STATUS_LABELS[status] || status || \"未知\";\n    }\n    function cleanOrderStatus(status){\n      status=String(status||\"pending\").trim();\n      return ORDER_STATUS_LABELS[status] ? status : \"pending\";\n    }\n    function normalizeOrder(order={}){\n      const now=Date.now();\n      const plan=ctx.planById(order.planId||\"monthly\");\n      const username=String(order.username||\"\").trim();\n      const createdAt=Number(order.createdAt)||now;\n      return {\n        id:String(order.id||ctx.uid(\"sub_order\")),\n        username,\n        planId:plan.id,\n        planName:String(order.planName||plan.name||plan.id),\n        status:cleanOrderStatus(order.status),\n        amountText:String(order.amountText||plan.priceText||\"\"),\n        originalPriceText:String(order.originalPriceText||plan.originalPriceText||\"\"),\n        discountPercent:String(order.discountPercent||plan.discountPercent||\"\"),\n        discountText:String(order.discountText||plan.discountText||\"\"),\n        createdAt,\n        updatedAt:Number(order.updatedAt)||createdAt,\n        approvedAt:Number(order.approvedAt)||0,\n        cancelledAt:Number(order.cancelledAt)||0,\n        approvedBy:String(order.approvedBy||\"\"),\n        cancelledBy:String(order.cancelledBy||\"\"),\n        actor:String(order.actor||username||ctx.currentUsername()||\"student\"),\n        source:String(order.source||\"student_request\"),\n        note:String(order.note||\"\"),\n        adminNote:String(order.adminNote||\"\"),\n        currentPlanId:String(order.currentPlanId||\"\"),\n        currentPlanName:String(order.currentPlanName||\"\"),\n        snapshot:order.snapshot && typeof order.snapshot===\"object\" ? order.snapshot : {\n          planId:plan.id,\n          planName:plan.name,\n          priceText:plan.priceText,\n          originalPriceText:plan.originalPriceText,\n          discountPercent:plan.discountPercent,\n          discountText:plan.discountText,\n          usageText:ctx.planUsageText(plan),\n          benefits:ctx.planBenefitItems(plan)\n        }\n      };\n    }\n    function readOrders(){\n      const raw=ctx.readJSON(ORDER_KEY,[]);\n      const list=Array.isArray(raw) ? raw : [];\n      return list.map(normalizeOrder).filter(order=>order.id && order.username);\n    }\n    function saveOrders(list){\n      const out=(Array.isArray(list)?list:[]).map(normalizeOrder).filter(order=>order.id && order.username).slice(0,500);\n      ctx.writeJSON(ORDER_KEY,out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-order-change\",{detail:{orders:out}}));\n      return out;\n    }\n    function orderList(options={}){\n      let list=readOrders();\n      if(options.username) list=list.filter(order=>order.username===String(options.username).trim());\n      if(options.status) list=list.filter(order=>order.status===String(options.status).trim());\n      return list.sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));\n    }\n    function pendingOrders(){\n      return orderList({status:\"pending\"});\n    }\n    function currentUserOrders(){\n      const username=ctx.currentUsername();\n      return username ? orderList({username}) : [];\n    }\n    function hasPendingOrder(username,planId){\n      username=String(username||ctx.currentUsername()||\"\").trim();\n      planId=ctx.normalizePlanId(planId||\"monthly\");\n      return !!orderList({username,status:\"pending\"}).find(order=>order.planId===planId);\n    }\n    function createOrder(planId,options={}){\n      const plan=ctx.planById(planId||\"monthly\");\n      const user=options.user || ctx.currentUser();\n      const username=String(options.username || (user&&user.username) || ctx.currentUsername() || \"\").trim();\n      if(!username) return {ok:false,message:\"请先登录学员账号后再提交订阅申请。\"};\n      const role=String(options.role || (user&&user.role) || ctx.currentRole() || \"guest\");\n      if(role===\"admin\"||role===\"teacher\") return {ok:false,message:\"当前身份不需要订阅，可直接使用管理或教学能力。\"};\n      if(role===\"viewer\"||role===\"guest\") return {ok:false,message:\"游客不进入订阅体系，请切换为学员账号后提交订阅申请。\"};\n      if(role!==\"student\") return {ok:false,message:\"只有学员账号需要开通订阅。\"};\n      if(plan.id===\"free\") return {ok:false,message:\"免费学员无需购买，可直接使用免费权益。\"};\n      const existing=orderList({username,status:\"pending\"}).find(order=>order.planId===plan.id);\n      if(existing) return {ok:true,duplicate:true,order:existing,message:`你已经提交过“${plan.name}”开通申请，管理员确认后会自动生效。`};\n      const current=ctx.subscriptionFor(username) || ctx.defaultSubscription(username);\n      const currentPlan=ctx.planById(current.planId||\"free\");\n      const order=normalizeOrder({\n        id:ctx.uid(\"sub_order\"),\n        username,\n        planId:plan.id,\n        planName:plan.name,\n        status:\"pending\",\n        amountText:plan.priceText||\"\",\n        originalPriceText:plan.originalPriceText||\"\",\n        discountPercent:plan.discountPercent||\"\",\n        discountText:plan.discountText||\"\",\n        createdAt:Date.now(),\n        updatedAt:Date.now(),\n        actor:username,\n        source:\"student_request\",\n        note:String(options.note||\"\"),\n        currentPlanId:currentPlan.id,\n        currentPlanName:currentPlan.name,\n        snapshot:{\n          planId:plan.id,\n          planName:plan.name,\n          priceText:plan.priceText,\n          originalPriceText:plan.originalPriceText,\n          discountPercent:plan.discountPercent,\n          discountText:plan.discountText,\n          usageText:ctx.planUsageText(plan),\n          benefits:ctx.planBenefitItems(plan)\n        }\n      });\n      const orders=readOrders();\n      orders.unshift(order);\n      saveOrders(orders);\n      ctx.logAction(\"提交订阅申请\",username,`${plan.name} · ${plan.priceText||\"待配置\"}`);\n      return {ok:true,order,message:`“${plan.name}”订阅申请已提交，请等待管理员确认开通。`};\n    }\n    function approveOrder(orderId,options={}){\n      const orders=readOrders();\n      const idx=orders.findIndex(order=>order.id===orderId);\n      if(idx<0) return {ok:false,message:\"未找到该订阅申请。\"};\n      const order={...orders[idx]};\n      if(order.status!==\"pending\") return {ok:false,message:`该申请当前状态为“${orderStatusLabel(order.status)}”，不能重复确认。`};\n      const actor=String(options.actor || ctx.currentActor() || ctx.currentUsername() || \"system-admin\");\n      const subscription=ctx.renewStudentSubscription(order.username,order.planId,{source:\"order\",orderId:order.id,note:options.note || `订单确认开通：${order.planName}`});\n      order.status=\"approved\";\n      order.approvedAt=Date.now();\n      order.approvedBy=actor;\n      order.updatedAt=Date.now();\n      order.adminNote=String(options.note||order.adminNote||\"\");\n      orders[idx]=normalizeOrder(order);\n      saveOrders(orders);\n      ctx.logAction(\"确认订阅开通\",order.username,`${order.planName} · 订单 ${order.id}`);\n      return {ok:true,order:orders[idx],subscription,message:`已为 ${order.username} 开通 ${order.planName}。`};\n    }\n    function cancelOrder(orderId,options={}){\n      const orders=readOrders();\n      const idx=orders.findIndex(order=>order.id===orderId);\n      if(idx<0) return {ok:false,message:\"未找到该订阅申请。\"};\n      const order={...orders[idx]};\n      if(order.status!==\"pending\") return {ok:false,message:`该申请当前状态为“${orderStatusLabel(order.status)}”，不能取消。`};\n      const actor=String(options.actor || ctx.currentActor() || ctx.currentUsername() || \"system-admin\");\n      order.status=\"cancelled\";\n      order.cancelledAt=Date.now();\n      order.cancelledBy=actor;\n      order.updatedAt=Date.now();\n      order.adminNote=String(options.note||order.adminNote||\"\");\n      orders[idx]=normalizeOrder(order);\n      saveOrders(orders);\n      ctx.logAction(\"取消订阅申请\",order.username,`${order.planName} · 订单 ${order.id}`);\n      return {ok:true,order:orders[idx],message:`已取消 ${order.username} 的 ${order.planName} 申请。`};\n    }\n    function removeOrder(orderId){\n      const orders=readOrders();\n      const next=orders.filter(order=>order.id!==orderId);\n      if(next.length===orders.length) return false;\n      saveOrders(next);\n      return true;\n    }\n\n    return {\n      ORDER_KEY,\n      ORDER_STATUS_LABELS,\n      readOrders,\n      saveOrders,\n      orderList,\n      pendingOrders,\n      currentUserOrders,\n      hasPendingOrder,\n      createOrder,\n      approveOrder,\n      cancelOrder,\n      removeOrder,\n      orderStatusLabel\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-orders.js"],["src/37-subscription-redeem-codes.js","\"use strict\";\n\n/*\n * 学员订阅卡密模块。\n *\n * 本文件只负责：卡密生成、查询、启停、删除与学员兑换。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionRedeemCodesModule = function(ctx={}){\n    const REDEEM_CODE_KEY = \"kg_student_subscription_redeem_codes_v1\";\n\n    const REDEEM_CODE_STATUS_LABELS = {\n      unused:\"未使用\",\n      used:\"已使用\",\n      disabled:\"已停用\"\n    };\n\n    function normalizeRedeemCodeText(value){\n      return String(value||\"\").trim().toUpperCase().replace(/\\s+/g,\"\");\n    }\n    function redeemCodeStatusLabel(status){\n      return REDEEM_CODE_STATUS_LABELS[status] || status || \"未知\";\n    }\n    function cleanRedeemCodeStatus(status){\n      status=String(status||\"unused\").trim();\n      return REDEEM_CODE_STATUS_LABELS[status] ? status : \"unused\";\n    }\n    function normalizeRedeemCode(record={}){\n      const now=Date.now();\n      const plan=ctx.planById(record.planId||\"monthly\");\n      const code=normalizeRedeemCodeText(record.code || randomRedeemCode());\n      const createdAt=Number(record.createdAt)||now;\n      return {\n        id:String(record.id||ctx.uid(\"redeem_code\")),\n        code,\n        planId:plan.id,\n        planName:String(record.planName||plan.name||plan.id),\n        status:cleanRedeemCodeStatus(record.status),\n        createdAt,\n        updatedAt:Number(record.updatedAt)||createdAt,\n        usedAt:Number(record.usedAt)||0,\n        usedBy:String(record.usedBy||\"\"),\n        createdBy:String(record.createdBy||ctx.currentUsername()||\"system-admin\"),\n        note:String(record.note||\"\"),\n        source:String(record.source||\"admin\")\n      };\n    }\n    function readRedeemCodes(){\n      const raw=ctx.readJSON(REDEEM_CODE_KEY,[]);\n      const list=Array.isArray(raw) ? raw : [];\n      return list.map(normalizeRedeemCode).filter(item=>item.code);\n    }\n    function saveRedeemCodes(list){\n      const seen=new Set();\n      const out=(Array.isArray(list)?list:[]).map(normalizeRedeemCode).filter(item=>{\n        if(!item.code || seen.has(item.code))return false;\n        seen.add(item.code);\n        return true;\n      }).slice(0,2000);\n      ctx.writeJSON(REDEEM_CODE_KEY,out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-redeem-code-change\",{detail:{codes:out}}));\n      return out;\n    }\n    function redeemCodeList(options={}){\n      let list=readRedeemCodes();\n      if(options.status) list=list.filter(item=>item.status===String(options.status));\n      if(options.planId) list=list.filter(item=>item.planId===ctx.normalizePlanId(options.planId));\n      if(options.keyword){\n        const kw=normalizeRedeemCodeText(options.keyword);\n        list=list.filter(item=>item.code.includes(kw) || String(item.usedBy||\"\").includes(options.keyword));\n      }\n      return list.sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));\n    }\n    function randomCodeGroup(len=4){\n      const chars=\"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\";\n      let out=\"\";\n      const c=globalThis.crypto;\n      if(c && c.getRandomValues){\n        const arr=new Uint8Array(len);\n        c.getRandomValues(arr);\n        for(let i=0;i<len;i++) out+=chars[arr[i]%chars.length];\n      }else{\n        for(let i=0;i<len;i++) out+=chars[Math.floor(Math.random()*chars.length)];\n      }\n      return out;\n    }\n    function randomRedeemCode(prefix=\"VIP\"){\n      const safePrefix=normalizeRedeemCodeText(prefix||\"VIP\").replace(/[^A-Z0-9]/g,\"\").slice(0,8)||\"VIP\";\n      return `${safePrefix}-${randomCodeGroup()}-${randomCodeGroup()}-${randomCodeGroup()}`;\n    }\n    function generateRedeemCodes(options={}){\n      const plan=ctx.planById(options.planId||\"monthly\");\n      if(plan.id===\"free\") return {ok:false,message:\"免费学员无需生成卡密。\"};\n      const count=Math.max(1,Math.min(200,Math.round(Number(options.count)||1)));\n      const prefix=options.prefix || (plan.shortName || plan.id || \"VIP\");\n      const note=String(options.note||\"\");\n      const codes=readRedeemCodes();\n      const existing=new Set(codes.map(item=>item.code));\n      const created=[];\n      let guard=0;\n      while(created.length<count && guard<count*20){\n        guard++;\n        const code=randomRedeemCode(prefix);\n        if(existing.has(code))continue;\n        existing.add(code);\n        created.push(normalizeRedeemCode({\n          id:ctx.uid(\"redeem_code\"),\n          code,\n          planId:plan.id,\n          planName:plan.name,\n          status:\"unused\",\n          createdAt:Date.now(),\n          updatedAt:Date.now(),\n          createdBy:String(options.createdBy||ctx.currentUsername()||\"system-admin\"),\n          note\n        }));\n      }\n      if(!created.length) return {ok:false,message:\"卡密生成失败，请重试。\"};\n      saveRedeemCodes([...created,...codes]);\n      ctx.logAction(\"生成订阅卡密\",\"SYSTEM\",`${plan.name} × ${created.length}`);\n      return {ok:true,codes:created,message:`已生成 ${created.length} 张 ${plan.name} 卡密。`};\n    }\n    function updateRedeemCode(id,patch={}){\n      const list=readRedeemCodes();\n      const idx=list.findIndex(item=>item.id===id || item.code===normalizeRedeemCodeText(id));\n      if(idx<0) return null;\n      const next=normalizeRedeemCode({...list[idx],...patch,updatedAt:Date.now()});\n      list[idx]=next;\n      saveRedeemCodes(list);\n      return next;\n    }\n    function disableRedeemCode(id){\n      const code=updateRedeemCode(id,{status:\"disabled\"});\n      if(code) ctx.logAction(\"停用订阅卡密\",\"SYSTEM\",code.code);\n      return code;\n    }\n    function enableRedeemCode(id){\n      const code=updateRedeemCode(id,{status:\"unused\",usedAt:0,usedBy:\"\"});\n      if(code) ctx.logAction(\"启用订阅卡密\",\"SYSTEM\",code.code);\n      return code;\n    }\n    function removeRedeemCode(id){\n      const list=readRedeemCodes();\n      const target=list.find(item=>item.id===id || item.code===normalizeRedeemCodeText(id));\n      const next=list.filter(item=>item.id!==id && item.code!==normalizeRedeemCodeText(id));\n      if(next.length===list.length) return false;\n      saveRedeemCodes(next);\n      ctx.logAction(\"删除订阅卡密\",\"SYSTEM\",target?target.code:String(id||\"\"));\n      return true;\n    }\n    function redeemCode(input,options={}){\n      const codeText=normalizeRedeemCodeText(input);\n      if(!codeText) return {ok:false,message:\"请输入卡密。\"};\n      const user=options.user || ctx.currentUser();\n      const username=String(options.username || (user&&user.username) || ctx.currentUsername() || \"\").trim();\n      if(!username) return {ok:false,message:\"请先登录学员账号后再使用卡密。\"};\n      const role=String(options.role || (user&&user.role) || ctx.currentRole() || \"guest\");\n      if(role===\"admin\"||role===\"teacher\") return {ok:false,message:\"当前身份不需要订阅卡密。\"};\n      if(role===\"viewer\"||role===\"guest\") return {ok:false,message:\"游客不进入订阅体系，请切换为学员账号后使用卡密。\"};\n      if(role!==\"student\") return {ok:false,message:\"只有学员账号可以使用订阅卡密。\"};\n      const list=readRedeemCodes();\n      const idx=list.findIndex(item=>item.code===codeText);\n      if(idx<0) return {ok:false,message:\"卡密不存在，请核对后重试。\"};\n      const item={...list[idx]};\n      if(item.status===\"used\") return {ok:false,message:`该卡密已被 ${item.usedBy||\"其他账号\"} 使用。`};\n      if(item.status===\"disabled\") return {ok:false,message:\"该卡密已停用，请联系管理员。\"};\n      const subscription=ctx.renewStudentSubscription(username,item.planId,{source:\"redeem_code\",orderId:item.id,note:`卡密兑换：${item.code}`});\n      item.status=\"used\";\n      item.usedAt=Date.now();\n      item.usedBy=username;\n      item.updatedAt=Date.now();\n      list[idx]=normalizeRedeemCode(item);\n      saveRedeemCodes(list);\n      ctx.logAction(\"兑换订阅卡密\",username,`${item.planName} · ${item.code}`);\n      return {ok:true,code:list[idx],subscription,message:`卡密兑换成功，已开通/续费 ${item.planName}。`};\n    }\n\n    return {\n      REDEEM_CODE_KEY,\n      REDEEM_CODE_STATUS_LABELS,\n      readRedeemCodes,\n      saveRedeemCodes,\n      redeemCodeList,\n      generateRedeemCodes,\n      redeemCode,\n      disableRedeemCode,\n      enableRedeemCode,\n      removeRedeemCode,\n      redeemCodeStatusLabel\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-redeem-codes.js"],["src/37-subscription-core.js","\"use strict\";\n\n/*\n * 学员订阅权益核心模块。\n *\n * 设计边界：\n * - admin 管理员：系统管理角色，自动绕过订阅限制。\n * - teacher 教师/教研：教学维护角色，自动绕过订阅限制。\n * - student 学员：唯一需要订阅权益判断的角色。\n * - viewer 游客：体验/只读角色，不进入订阅体系，只能使用公开示例能力。\n * - guest 未登录访客：不进入订阅体系。\n *\n * 订阅与套餐数据由 FastAPI 注入页面内存，权益以服务端校验为准。\n *\n * 基线重构 A：套餐、订单、卡密已拆到独立模块；本文件保留统一入口、\n * 订阅状态、权益校验、页面装饰和 window.KGSubscription 对外 API。\n */\n(function(){\n  const Auth = window.KGAuthCore || {};\n  const memoryRecords = new Map();\n  let subscriptionState = Object.freeze({});\n  const ACTIVE_STATUSES = new Set([\"active\",\"trial\",\"manual\"]);\n\n  const STATUS_LABELS = {\n    active:\"有效\",\n    expired:\"已过期\",\n    paused:\"已停用\",\n    cancelled:\"已取消\",\n    trial:\"试用中\",\n    manual:\"手动开通\"\n  };\n  const SOURCE_LABELS = new Map([\n    [\"default\",\"默认\"],[\"manual\",\"管理员调整\"],[\"redeem_code\",\"兑换码\"],\n    [\"wechat_pay\",\"微信支付\"],[\"order\",\"订单开通\"],[\"referral\",\"推荐奖励\"]\n  ]);\n  function sourceLabel(source){ return SOURCE_LABELS.get(source) || \"其他来源\"; }\n\n  function readMemory(key,fallback){return memoryRecords.has(key)?memoryRecords.get(key):fallback}\n  function writeMemory(key,value){memoryRecords.set(key,value);return true}\n  function roleApi(){\n    return window.KGRolePermissions || null;\n  }\n  function currentUser(){\n    if(Auth.currentUser) return Auth.currentUser();\n    const api=roleApi();\n    return api && typeof api.currentUser===\"function\" ? api.currentUser() : null;\n  }\n  function currentRole(){\n    const api=roleApi();\n    return api && typeof api.currentRole===\"function\" ? api.currentRole() : \"guest\";\n  }\n  function currentUsername(){\n    if(Auth.currentUsername) return Auth.currentUsername();\n    const user=currentUser();\n    return user && user.username || \"\";\n  }\n  function currentActor(){\n    return Auth.currentActor ? Auth.currentActor() : currentUsername();\n  }\n  function uid(prefix=\"sub_order\"){\n    if(Auth.uid) return Auth.uid(prefix);\n    const c=globalThis.crypto;\n    return prefix + \"-\" + (c && c.randomUUID ? c.randomUUID() : Math.random().toString(36).slice(2)+Date.now().toString(36));\n  }\n  function logAction(action, username, detail){\n    if(Auth.logAction) Auth.logAction(action, username, detail);\n  }\n\n  const PlansFactory = window.KGSubscriptionPlansModule;\n  const OrdersFactory = window.KGSubscriptionOrdersModule;\n  const RedeemCodesFactory = window.KGSubscriptionRedeemCodesModule;\n  if(typeof PlansFactory !== \"function\" || typeof OrdersFactory !== \"function\" || typeof RedeemCodesFactory !== \"function\"){\n    console.error(\"订阅模块加载顺序异常：请先加载 plans / orders / redeem-codes，再加载 37-subscription-core.js\");\n    return;\n  }\n\n  const Plans = PlansFactory({readJSON:readMemory,writeJSON:writeMemory,decorateSubscriptionElements});\n\n  function normalizePlanId(planId){ return Plans.normalizePlanId(planId); }\n  function basePlanById(planId){ return Plans.basePlanById(planId); }\n  function planById(planId){ return Plans.planById(planId); }\n  function planList(options={}){ return Plans.planList(options); }\n  function enabledPlanList(){ return Plans.enabledPlanList(); }\n  function expiresAtForPlan(planId,startedAt=Date.now()){ return Plans.expiresAtForPlan(planId,startedAt); }\n  function readPlanSettings(){ return Plans.readPlanSettings(); }\n  function savePlanSettings(settings){ return Plans.savePlanSettings(settings); }\n  function setPlanSettings(planId,patch={}){ return Plans.setPlanSettings(planId,patch); }\n  function resetPlanSettings(planId){ return Plans.resetPlanSettings(planId); }\n  function deriveDiscountPrice(originalText,discountPercent){ return Plans.deriveDiscountPrice(originalText,discountPercent); }\n  function deriveDiscountLabel(discountPercent){ return Plans.deriveDiscountLabel(discountPercent); }\n  function featureLabel(feature){ return Plans.featureLabel(feature); }\n  function planBenefitItems(plan){ return Plans.planBenefitItems(plan); }\n  function planUsageText(plan){ return Plans.planUsageText(plan); }\n  function defaultPlanBenefitItems(plan){ return Plans.defaultPlanBenefitItems(plan); }\n  function defaultPlanUsageText(plan){ return Plans.defaultPlanUsageText(plan); }\n\n  function isStudentRole(role=currentRole()){\n    return role === \"student\";\n  }\n  function isBypassRole(role=currentRole()){\n    return role === \"admin\" || role === \"teacher\";\n  }\n  function isVisitorRole(role=currentRole()){\n    return role === \"viewer\" || role === \"guest\";\n  }\n  function normalizeStatus(status){\n    const next=String(status || \"active\").trim();\n    return STATUS_LABELS[next] ? next : \"active\";\n  }\n  function readSubscriptions(){\n    return {...subscriptionState};\n  }\n  function saveSubscriptions(map){\n    subscriptionState=Object.freeze(Object.fromEntries(\n      Object.entries(map&&typeof map===\"object\"?map:{}).map(([username,subscription])=>[\n        username,Object.freeze(normalizeSubscription(subscription,username))\n      ])\n    ));\n    return readSubscriptions();\n  }\n  function hydrateSubscriptions(map,options={}){\n    const incoming=map&&typeof map===\"object\"?map:{};\n    return saveSubscriptions(options.merge?{...subscriptionState,...incoming}:incoming);\n  }\n  function hydratePlanSettings(settings,options={}){\n    const next=options.merge?{...Plans.readPlanSettings(),...(settings||{})}:(settings||{});\n    Plans.savePlanSettings(next);\n    return Plans.readPlanSettings();\n  }\n  function defaultSubscription(username=currentUsername()){\n    const now=Date.now();\n    return {\n      username,\n      planId:\"free\",\n      status:\"active\",\n      startedAt:now,\n      expiresAt:0,\n      updatedAt:now,\n      source:\"default\",\n      orderId:\"\",\n      note:\"\"\n    };\n  }\n  function subscriptionTime(value,fallback=0){\n    if(typeof value===\"number\"&&Number.isFinite(value))return value;\n    const parsed=Date.parse(String(value||\"\"));\n    return Number.isFinite(parsed)?parsed:fallback;\n  }\n  function normalizeSubscription(sub,username=currentUsername()){\n    sub=sub && typeof sub === \"object\" ? sub : {};\n    const planId=normalizePlanId(sub.planId);\n    const startedAt=subscriptionTime(sub.startedAt,Date.now());\n    let expiresAt=subscriptionTime(sub.expiresAt,0);\n    const plan=planById(planId);\n    if(plan.durationDays === -1) expiresAt=0;\n    return {\n      ...defaultSubscription(username),\n      ...sub,\n      username:sub.username || username,\n      planId,\n      status:normalizeStatus(sub.status),\n      startedAt,\n      expiresAt,\n      updatedAt:subscriptionTime(sub.updatedAt,0),\n      source:sub.source || \"manual\",\n      orderId:sub.orderId || \"\",\n      note:sub.note || \"\"\n    };\n  }\n  function isExpired(sub){\n    const plan=planById(sub && sub.planId);\n    if(plan.durationDays === -1) return false;\n    return !!(sub && Number(sub.expiresAt) && Date.now() > Number(sub.expiresAt));\n  }\n  function effectiveSubscription(sub,username=currentUsername()){\n    const next=normalizeSubscription(sub,username);\n    if(isExpired(next)) return {...next,status:\"expired\"};\n    return next;\n  }\n  function subscriptionFor(username){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const map=readSubscriptions();\n    return effectiveSubscription(map[username],username);\n  }\n  function currentSubscription(){\n    const role=currentRole();\n    const user=currentUser();\n    if(!user || !isStudentRole(role)) return null;\n    return subscriptionFor(user.username);\n  }\n  function currentPlan(){\n    const role=currentRole();\n    if(isBypassRole(role)){\n      return {id:\"role_bypass\",name:\"管理/教学免订阅\",shortName:\"免订阅\",level:99,features:{},limits:{},durationText:\"不需要订阅\"};\n    }\n    if(isVisitorRole(role)){\n      return {id:\"visitor\",name:\"游客体验\",shortName:\"游客\",level:-1,features:{demoOnly:true},limits:{},durationText:\"体验\"};\n    }\n    const sub=currentSubscription();\n    return planById(sub && sub.planId);\n  }\n  function statusLabel(status){\n    return STATUS_LABELS[status] || status || \"未知\";\n  }\n  function canUse(feature, options={}){\n    const role=currentRole();\n    if(isBypassRole(role)) return true;\n    if(isVisitorRole(role)) return !!options.allowVisitorDemo;\n    if(!isStudentRole(role)) return false;\n    const sub=currentSubscription();\n    if(!sub || !ACTIVE_STATUSES.has(sub.status)) return false;\n    const plan=planById(sub.planId);\n    if(!feature) return true;\n    return !!(plan && plan.features && plan.features[feature]);\n  }\n  function requireFeature(feature, options={}){\n    const allowed=canUse(feature, options);\n    if(allowed) return true;\n    const role=currentRole();\n    let message=\"\";\n    if(isVisitorRole(role)) message=\"游客不参与订阅，请登录学员账号后使用“\"+featureLabel(feature)+\"”。\";\n    else if(isStudentRole(role)) message=\"当前学员订阅暂未包含“\"+featureLabel(feature)+\"”。\";\n    else message=\"当前角色不可使用“\"+featureLabel(feature)+\"”。\";\n    const status=document.getElementById(\"status\");\n    if(status && typeof window.showStatus===\"function\") window.showStatus(message);\n    else if(status){\n      status.textContent=message;\n      status.classList.add(\"show\");\n      clearTimeout(requireFeature.timer);\n      requireFeature.timer=setTimeout(()=>status.classList.remove(\"show\"),2200);\n    }\n    return false;\n  }\n  function usageLimit(key){\n    const role=currentRole();\n    if(isBypassRole(role)) return -1;\n    if(isVisitorRole(role)) return 0;\n    const plan=currentPlan();\n    return plan && plan.limits && Number.isFinite(Number(plan.limits[key])) ? Number(plan.limits[key]) : 0;\n  }\n  function limitLabel(key){\n    return Plans.LIMIT_LABELS[key] || key;\n  }\n  function remainingUsage(key,currentCount=0){\n    const limit=usageLimit(key);\n    if(limit < 0) return -1;\n    return Math.max(0,limit-(Number(currentCount)||0));\n  }\n  function showSubscriptionMessage(message){\n    const text=String(message||\"\").trim();\n    if(!text) return;\n    if(typeof window.showStatus===\"function\"){\n      window.showStatus(text);\n      return;\n    }\n    const status=document.getElementById(\"status\");\n    if(status){\n      status.textContent=text;\n      status.classList.add(\"show\");\n      clearTimeout(showSubscriptionMessage.timer);\n      showSubscriptionMessage.timer=setTimeout(()=>status.classList.remove(\"show\"),2800);\n      return;\n    }\n    let toast=document.getElementById(\"subscriptionLimitToast\");\n    if(!toast){\n      toast=document.createElement(\"div\");\n      toast.id=\"subscriptionLimitToast\";\n      toast.className=\"subscription-limit-toast\";\n      toast.setAttribute(\"role\",\"status\");\n      document.body.appendChild(toast);\n    }\n    toast.textContent=text;\n    toast.classList.add(\"show\");\n    clearTimeout(showSubscriptionMessage.toastTimer);\n    showSubscriptionMessage.toastTimer=setTimeout(()=>toast.classList.remove(\"show\"),3000);\n  }\n  function usageLimitMessage(key,currentCount=0,addCount=1,options={}){\n    const role=currentRole();\n    const label=options.label || limitLabel(key);\n    if(isVisitorRole(role)) return `游客账号不能新增${label}，请登录学员账号后使用。`;\n    const limit=usageLimit(key);\n    if(limit < 0) return \"\";\n    const current=Math.max(0,Number(currentCount)||0);\n    const add=Math.max(1,Number(addCount)||1);\n    const plan=currentPlan();\n    const planName=plan && (plan.name||plan.shortName) || \"当前套餐\";\n    return `${planName}的${label}上限为 ${limit} 个，当前已有 ${current} 个，本次还需新增 ${add} 个。升级会员后可解除此限制。`;\n  }\n  function canAddUsage(key,currentCount=0,addCount=1){\n    const limit=usageLimit(key);\n    if(limit < 0) return true;\n    const current=Math.max(0,Number(currentCount)||0);\n    const add=Math.max(1,Number(addCount)||1);\n    return current + add <= limit;\n  }\n  function requireUsageLimit(key,currentCount=0,addCount=1,options={}){\n    if(canAddUsage(key,currentCount,addCount)) return true;\n    showSubscriptionMessage(options.message || usageLimitMessage(key,currentCount,addCount,options));\n    return false;\n  }\n  function setStudentSubscription(username, patch={}){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const map=readSubscriptions();\n    const previous=normalizeSubscription(map[username],username);\n    const planId=patch.planId != null ? normalizePlanId(patch.planId) : previous.planId;\n    const startedAt=patch.startedAt != null ? Number(patch.startedAt)||Date.now() : (previous.startedAt || Date.now());\n    let expiresAt=patch.expiresAt != null ? Number(patch.expiresAt)||0 : previous.expiresAt;\n    if(patch.planId != null && patch.expiresAt == null) expiresAt=expiresAtForPlan(planId,startedAt);\n    const next=normalizeSubscription({\n      ...previous,\n      ...patch,\n      username,\n      planId,\n      startedAt,\n      expiresAt,\n      updatedAt:Date.now()\n    },username);\n    map[username]=next;\n    saveSubscriptions(map);\n    window.dispatchEvent(new CustomEvent(\"kg-subscription-change\",{detail:{username,subscription:next}}));\n    decorateSubscriptionElements();\n    return next;\n  }\n  function subscriptionText(){\n    const role=currentRole();\n    if(isBypassRole(role)) return \"免订阅\";\n    if(role===\"viewer\") return \"游客体验\";\n    if(role===\"guest\") return \"未登录游客\";\n    const sub=currentSubscription();\n    if(!sub) return \"无订阅\";\n    const plan=planById(sub.planId);\n    if(ACTIVE_STATUSES.has(sub.status)) return plan.shortName || plan.name || \"免费\";\n    return (plan.shortName || plan.name || \"订阅\") + \" · \" + statusLabel(sub.status);\n  }\n  function formatDate(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"永久有效\";\n    try{return new Date(n).toLocaleDateString(\"zh-CN\")}catch(e){return \"—\"}\n  }\n  function formatDateTime(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"永久有效\";\n    try{return new Date(n).toLocaleString(\"zh-CN\",{year:\"numeric\",month:\"2-digit\",day:\"2-digit\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false})}catch(e){return \"—\"}\n  }\n  function countdownDaysText(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"长期有效\";\n    const diff=n-Date.now();\n    if(diff <= 0) return \"已到期\";\n    return `剩余 ${Math.ceil(diff/(24*60*60*1000))} 天`;\n  }\n  function dateInputValue(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"\";\n    const d=new Date(n - new Date(n).getTimezoneOffset()*60000);\n    return d.toISOString().slice(0,10);\n  }\n  function dateInputToTime(value,endOfDay=false){\n    if(!value) return 0;\n    const suffix=endOfDay ? \"T23:59:59\" : \"T00:00:00\";\n    const t=new Date(String(value)+suffix).getTime();\n    return Number.isFinite(t) ? t : 0;\n  }\n  function renewStudentSubscription(username,planId,options={}){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const plan=planById(planId||\"monthly\");\n    const previous=subscriptionFor(username) || defaultSubscription(username);\n    const now=Date.now();\n    const extend=options.extend !== false;\n    const base=extend && plan.durationDays > 0 && previous.expiresAt && previous.expiresAt > now ? previous.expiresAt : now;\n    const startedAt=Number(options.startedAt)||now;\n    const expiresAt=plan.durationDays === -1 ? 0 : (plan.durationDays > 0 ? base + plan.durationDays*24*60*60*1000 : 0);\n    return setStudentSubscription(username,{\n      planId:plan.id,\n      status:options.status || \"active\",\n      startedAt,\n      expiresAt,\n      source:options.source || \"manual\",\n      orderId:options.orderId || previous.orderId || \"\",\n      note:options.note != null ? String(options.note) : previous.note || \"\"\n    });\n  }\n  function pauseStudentSubscription(username,note=\"\"){\n    const previous=subscriptionFor(username) || defaultSubscription(username);\n    return setStudentSubscription(username,{...previous,status:\"paused\",note:String(note||previous.note||\"\"),source:previous.source||\"manual\"});\n  }\n  function activateFreeSubscription(username,note=\"\"){\n    return setStudentSubscription(username,{planId:\"free\",status:\"active\",startedAt:Date.now(),expiresAt:0,source:\"manual\",note:String(note||\"\")});\n  }\n  function subscriptionSummary(username=currentUsername()){\n    const sub=subscriptionFor(username);\n    if(!sub) return {subscription:null,plan:planById(\"free\"),sourceText:sourceLabel(),statusText:\"未开通\",expiresText:\"—\",expiresFullText:\"—\",countdownText:\"—\"};\n    const plan=planById(sub.planId);\n    const unlimited=plan.durationDays === -1 || !sub.expiresAt;\n    return {\n      subscription:sub,\n      plan,\n      sourceText:sourceLabel(sub.source),\n      statusText:statusLabel(sub.status),\n      expiresText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : formatDate(sub.expiresAt),\n      expiresFullText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : formatDateTime(sub.expiresAt),\n      countdownText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : countdownDaysText(sub.expiresAt)\n    };\n  }\n  function decorateSubscriptionElements(root=document){\n    const scope=root||document;\n    scope.querySelectorAll(\"[data-subscription-feature]\").forEach(el=>{\n      const feature=el.dataset.subscriptionFeature;\n      const mode=el.dataset.subscriptionMode || \"disable\";\n      const allowed=canUse(feature);\n      el.classList.toggle(\"subscription-locked\",!allowed);\n      el.setAttribute(\"aria-disabled\",String(!allowed));\n      if(mode===\"hide\") el.hidden=!allowed;\n      else if(\"disabled\" in el) el.disabled=!allowed;\n      if(!allowed && !el.dataset.subscriptionTitle){\n        el.dataset.subscriptionTitle=el.title || \"\";\n        el.title=\"当前学员订阅暂未包含：\"+featureLabel(feature);\n      }else if(allowed && el.dataset.subscriptionTitle!=null){\n        el.title=el.dataset.subscriptionTitle;\n      }\n    });\n    const status=scope.querySelector(\"[data-subscription-status]\");\n    if(status) status.textContent=subscriptionText();\n    const current=currentSubscription();\n    const hasActivePaidMembership=!!(current\n      && ACTIVE_STATUSES.has(current.status)\n      && current.planId\n      && current.planId!==\"free\");\n    scope.querySelectorAll(\"#upgradeMemberBtn,#accountMenuUpgradeBtn,[data-subscription-upgrade-label]\").forEach(btn=>{\n      btn.hidden=hasActivePaidMembership;\n      if(!hasActivePaidMembership) btn.textContent=\"升级会员\";\n    });\n  }\n\n  const Orders = OrdersFactory({\n    readJSON:readMemory,\n    writeJSON:writeMemory,\n    currentUser,\n    currentRole,\n    currentUsername,\n    currentActor,\n    uid,\n    logAction,\n    normalizePlanId,\n    planById,\n    planUsageText,\n    planBenefitItems,\n    subscriptionFor,\n    defaultSubscription,\n    renewStudentSubscription\n  });\n\n  const RedeemCodes = RedeemCodesFactory({\n    readJSON:readMemory,\n    writeJSON:writeMemory,\n    currentUser,\n    currentRole,\n    currentUsername,\n    uid,\n    logAction,\n    normalizePlanId,\n    planById,\n    renewStudentSubscription\n  });\n\n  function readOrders(){ return Orders.readOrders(); }\n  function saveOrders(list){ return Orders.saveOrders(list); }\n  function orderList(options={}){ return Orders.orderList(options); }\n  function pendingOrders(){ return Orders.pendingOrders(); }\n  function currentUserOrders(){ return Orders.currentUserOrders(); }\n  function hasPendingOrder(username,planId){ return Orders.hasPendingOrder(username,planId); }\n  function createOrder(planId,options={}){ return Orders.createOrder(planId,options); }\n  function approveOrder(orderId,options={}){ return Orders.approveOrder(orderId,options); }\n  function cancelOrder(orderId,options={}){ return Orders.cancelOrder(orderId,options); }\n  function removeOrder(orderId){ return Orders.removeOrder(orderId); }\n  function orderStatusLabel(status){ return Orders.orderStatusLabel(status); }\n\n  function readRedeemCodes(){ return RedeemCodes.readRedeemCodes(); }\n  function saveRedeemCodes(list){ return RedeemCodes.saveRedeemCodes(list); }\n  function redeemCodeList(options={}){ return RedeemCodes.redeemCodeList(options); }\n  function generateRedeemCodes(options={}){ return RedeemCodes.generateRedeemCodes(options); }\n  function redeemCode(input,options={}){ return RedeemCodes.redeemCode(input,options); }\n  function disableRedeemCode(id){ return RedeemCodes.disableRedeemCode(id); }\n  function enableRedeemCode(id){ return RedeemCodes.enableRedeemCode(id); }\n  function removeRedeemCode(id){ return RedeemCodes.removeRedeemCode(id); }\n  function redeemCodeStatusLabel(status){ return RedeemCodes.redeemCodeStatusLabel(status); }\n\n  document.addEventListener(\"DOMContentLoaded\",()=>decorateSubscriptionElements());\n  window.addEventListener(\"kg-role-theme-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-auth-session-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-auth-users-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-subscription-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-subscription-plan-change\",()=>setTimeout(decorateSubscriptionElements,0));\n\n  window.KGSubscription={\n    ORDER_KEY:Orders.ORDER_KEY,\n    REDEEM_CODE_KEY:RedeemCodes.REDEEM_CODE_KEY,\n    PLANS:Plans.PLANS,\n    PLAN_ORDER:Plans.PLAN_ORDER,\n    PLAN_ALIASES:Plans.PLAN_ALIASES,\n    FEATURE_LABELS:Plans.FEATURE_LABELS,\n    LIMIT_LABELS:Plans.LIMIT_LABELS,\n    STATUS_LABELS,\n    ORDER_STATUS_LABELS:Orders.ORDER_STATUS_LABELS,\n    REDEEM_CODE_STATUS_LABELS:RedeemCodes.REDEEM_CODE_STATUS_LABELS,\n    readSubscriptions,\n    saveSubscriptions,\n    hydrateSubscriptions,\n    hydratePlanSettings,\n    readOrders,\n    saveOrders,\n    readRedeemCodes,\n    saveRedeemCodes,\n    redeemCodeList,\n    generateRedeemCodes,\n    redeemCode,\n    disableRedeemCode,\n    enableRedeemCode,\n    removeRedeemCode,\n    redeemCodeStatusLabel,\n    orderList,\n    pendingOrders,\n    currentUserOrders,\n    hasPendingOrder,\n    createOrder,\n    approveOrder,\n    cancelOrder,\n    removeOrder,\n    orderStatusLabel,\n    readPlanSettings,\n    savePlanSettings,\n    setPlanSettings,\n    resetPlanSettings,\n    normalizePlanId,\n    basePlanById,\n    planById,\n    planList,\n    enabledPlanList,\n    expiresAtForPlan,\n    subscriptionFor,\n    currentSubscription,\n    currentPlan,\n    currentRole,\n    isStudentRole,\n    isBypassRole,\n    isVisitorRole,\n    canUse,\n    requireFeature,\n    usageLimit,\n    limitLabel,\n    remainingUsage,\n    canAddUsage,\n    requireUsageLimit,\n    usageLimitMessage,\n    showSubscriptionMessage,\n    setStudentSubscription,\n    renewStudentSubscription,\n    pauseStudentSubscription,\n    activateFreeSubscription,\n    subscriptionSummary,\n    formatDate,\n    formatDateTime,\n    countdownDaysText,\n    deriveDiscountPrice,\n    deriveDiscountLabel,\n    dateInputValue,\n    dateInputToTime,\n    subscriptionText,\n    decorateSubscriptionElements,\n    featureLabel,\n    planBenefitItems,\n    planUsageText,\n    defaultPlanBenefitItems,\n    defaultPlanUsageText,\n    statusLabel,\n    sourceLabel,\n    normalizeSubscription\n  };\n})();\n//# sourceURL=src/37-subscription-core.js"],["direct-system-adapter.js","'use strict'\n\n;(function (global) {\n  const api = global.KGDomainApi\n  const roleApi = global.KGRolePermissions\n  const subscriptionApi = global.KGSubscription\n  const auth = global.KGAuthCore\n  const wechatApi = global.KGWechatLogin\n  if (!api || !roleApi || !subscriptionApi) return\n\n  let userProfile = global.__KG_DIRECT_BOOTSTRAP__?.authenticated\n    ? global.__KG_DIRECT_BOOTSTRAP__.authUser || null\n    : null\n  let orderState = Object.freeze([])\n  let redeemCodeState = Object.freeze([])\n  let initialization = Object.freeze({ status: 'loading', error: null })\n  let subscriptionRequest = 0\n  let subscriptionFlight = null\n\n  function request(method, path, body) {\n    return api.request({ method, path, body })\n  }\n\n  function toLegacyTheme(theme = {}) {\n    return Object.freeze({\n      primary: theme.primary_color || theme.primary,\n      accent: theme.accent_color || theme.accent,\n      soft: theme.soft_color || theme.soft,\n      text: theme.text_color || theme.text,\n    })\n  }\n\n  function toServerTheme(theme = {}) {\n    return {\n      primary_color: theme.primary,\n      accent_color: theme.accent,\n      soft_color: theme.soft,\n      text_color: theme.text,\n    }\n  }\n\n  function planSettings(plans = []) {\n    return Object.freeze(Object.fromEntries(\n      plans.filter(plan => plan && (plan.planId || plan.id)).map(plan => {\n        const planId = plan.planId || plan.id\n        return [planId, Object.freeze({ ...plan, id: undefined, planId: undefined })]\n      }),\n    ))\n  }\n\n  function subscriptionTimestamp(value) {\n    if (typeof value === 'number') return value\n    const timestamp = Date.parse(value || '')\n    return Number.isFinite(timestamp) ? timestamp : 0\n  }\n\n  function normalizeSubscription(subscription = {}) {\n    return Object.freeze({\n      ...subscription,\n      username: subscription.username || userProfile?.username || '',\n      startedAt: subscriptionTimestamp(subscription.startedAt || subscription.started_at),\n      expiresAt: subscriptionTimestamp(subscription.expiresAt || subscription.expires_at),\n      updatedAt: subscriptionTimestamp(subscription.updatedAt || subscription.updated_at),\n    })\n  }\n\n  function normalizeOrder(order = {}) {\n    const amount = Number(order.amount)\n    return Object.freeze({\n      ...order,\n      id: String(order.id || ''),\n      username: String(order.username || ''),\n      planId: String(order.planId || order.plan_id || ''),\n      planName: String(order.planName || order.plan_name || ''),\n      note: String(order.note || ''),\n      adminNote: String(order.adminNote || order.admin_note || ''),\n      createdAt: subscriptionTimestamp(order.createdAt || order.created_at),\n      updatedAt: subscriptionTimestamp(order.updatedAt || order.updated_at),\n      approvedAt: subscriptionTimestamp(order.approvedAt || order.approved_at),\n      amountText: Number.isFinite(amount) ? `￥${(amount / 100).toFixed(2)}` : '',\n    })\n  }\n\n  function normalizeRedeemCode(code = {}) {\n    return Object.freeze({\n      ...code,\n      id: String(code.id || ''),\n      code: String(code.code || '').trim().toUpperCase(),\n      planId: String(code.planId || code.plan_id || ''),\n      planName: String(code.planName || code.plan_name || ''),\n      createdAt: subscriptionTimestamp(code.createdAt || code.created_at),\n      usedAt: subscriptionTimestamp(code.usedAt || code.used_at),\n    })\n  }\n\n  function filteredRecords(records, options = {}) {\n    return records.filter(record => Object.entries(options).every(([key, value]) => (\n      value == null || value === '' || String(record[key] || '') === String(value)\n    )))\n  }\n\n  async function refreshUserProfile() {\n    if (userProfile) return userProfile\n    const payload = await request('GET', '/api/v1/auth/me')\n    userProfile = payload?.user || null\n    return userProfile\n  }\n\n  async function refreshRoleThemes() {\n    const payload = await request('GET', '/api/v1/system/themes')\n    const next = Object.freeze(Object.fromEntries(\n      Object.entries(payload.themes || {}).map(([role, theme]) => [role, toLegacyTheme(theme)]),\n    ))\n    roleApi.hydrateThemes?.(next)\n    return next\n  }\n\n  async function refreshPlans() {\n    const payload = await request('GET', '/api/v1/subscriptions/plans')\n    const next = planSettings(payload.plans || [])\n    subscriptionApi.hydratePlanSettings?.(next)\n    global.KGSubscriptionRemotePlanSettings = next\n    global.dispatchEvent?.(new CustomEvent('kg-subscription-plan-change', { detail: { settings: next } }))\n    return next\n  }\n\n  async function refreshSubscription() {\n    const owner = String(auth?.currentUser?.()?.username || userProfile?.username || '')\n    if (!owner) return null\n    if (subscriptionFlight?.owner === owner && subscriptionFlight.revision === subscriptionRequest) return subscriptionFlight.promise\n    const revision = ++subscriptionRequest\n    const promise = (async () => {\n      const payload = await request('GET', '/api/v1/subscriptions/me')\n      if (revision !== subscriptionRequest || owner !== String(auth?.currentUser?.()?.username || userProfile?.username || '')\n          || (payload.subscription?.username && payload.subscription.username !== owner)) return null\n      const subscription = payload.subscription ? normalizeSubscription(payload.subscription) : null\n      subscriptionApi.hydrateSubscriptions?.(\n        subscription?.username ? { [subscription.username]: subscription } : {},\n        { merge: true },\n      )\n      global.KGServerEntitlements = Object.freeze({ allExamPapers: payload.entitlements?.allExamPapers === true })\n      return subscription\n    })()\n    subscriptionFlight = { owner, revision, promise }\n    try { return await promise } finally { if (subscriptionFlight?.promise === promise) subscriptionFlight = null }\n  }\n\n  async function refreshAdminSettings() {\n    const [wechat, wechatPay] = await Promise.all([\n      request('GET', '/api/v1/system/wechat-config'),\n      request('GET', '/api/v1/system/wechat-pay-config'),\n    ])\n    wechatApi?.applyConfig?.(wechat.config || {})\n    global.KGDirectSystemSettings = Object.freeze({\n      wechatPayConfig: Object.freeze({ ...(wechatPay.config || {}) }),\n    })\n    return global.KGDirectSystemSettings\n  }\n\n  async function refreshAdminLogs() {\n    const payload = await request('GET', '/api/v1/system/logs?limit=100')\n    auth?.replaceAdminLogs?.(payload.logs || [])\n    return payload.logs || []\n  }\n\n  async function refreshOrders() {\n    const payload = await request('GET', '/api/v1/subscriptions/orders')\n    orderState = Object.freeze((payload.orders || []).map(normalizeOrder))\n    global.dispatchEvent?.(new CustomEvent('kg-subscription-order-change', { detail: { orders: orderState } }))\n    return orderState\n  }\n\n  async function refreshRedeemCodes() {\n    const payload = await request('GET', '/api/v1/subscriptions/redeem-codes')\n    redeemCodeState = Object.freeze((payload.codes || []).map(normalizeRedeemCode))\n    global.dispatchEvent?.(new CustomEvent('kg-subscription-redeem-code-change', { detail: { codes: redeemCodeState } }))\n    return redeemCodeState\n  }\n\n  async function clearAdminLogs() {\n    await request('DELETE', '/api/v1/system/logs')\n    auth?.replaceAdminLogs?.([])\n    return []\n  }\n\n  async function refreshAuthenticatedContext() {\n    await refreshPlans()\n    try { await refreshUserProfile() } catch (_) { userProfile = null }\n    if (!userProfile) {\n      global.KGServerEntitlements = Object.freeze({ allExamPapers: false })\n      return null\n    }\n    await Promise.all([refreshRoleThemes(), refreshSubscription()])\n    if (userProfile.role === 'admin') {\n      // 按需加载：管理日志/订单/兑换码仅管理页消费（约 50KB+），不在其他页面预取。\n      if (/\\/(admin-console|admin-settings|admin-operations|user-management|feedback-management|message-management|system-settings)\\.html/.test(global.location?.pathname || '')) {\n        await Promise.all([refreshAdminSettings(), refreshAdminLogs(), refreshOrders(), refreshRedeemCodes()])\n      } else {\n        await refreshAdminSettings()\n      }\n    }\n    return userProfile\n  }\n\n  async function saveTheme(role, theme) {\n    const payload = await request('PUT', `/api/v1/system/themes/${encodeURIComponent(role)}`, toServerTheme(theme))\n    return roleApi.hydrateTheme?.(role, toLegacyTheme(payload.theme))\n      || roleApi.saveTheme(role, toLegacyTheme(payload.theme))\n  }\n\n  async function resetTheme(role) {\n    const fallback = roleApi.DEFAULT_THEMES?.[role] || {}\n    return saveTheme(role, fallback)\n  }\n\n  async function saveWechatConfig(config) {\n    const payload = await request('PUT', '/api/v1/system/wechat-config', config)\n    wechatApi?.applyConfig?.(payload.config || {})\n    return payload.config || {}\n  }\n\n  async function savePlan(planId, patch) {\n    const payload = await request('PUT', `/api/v1/system/subscription-plans/${encodeURIComponent(planId)}`, patch)\n    subscriptionApi.hydratePlanSettings?.({ [planId]: payload.plan || patch }, { merge: true })\n    return subscriptionApi.planById?.(planId) || payload.plan || patch\n  }\n\n  async function saveAllPlans(settings = {}) {\n    for (const planId of subscriptionApi.PLAN_ORDER || []) {\n      await savePlan(planId, settings[planId] || subscriptionApi.PLANS?.[planId] || {})\n    }\n    return subscriptionApi.readPlanSettings?.() || settings\n  }\n\n  async function setStudentSubscription(username, patch = {}) {\n    const body = {}\n    for (const key of ['planId', 'status', 'note']) {\n      if (Object.prototype.hasOwnProperty.call(patch, key)) body[key] = patch[key]\n    }\n    for (const key of ['startedAt', 'expiresAt']) {\n      if (!Object.prototype.hasOwnProperty.call(patch, key)) continue\n      const timestamp = Number(patch[key]) || 0\n      body[key] = timestamp ? new Date(timestamp).toISOString() : null\n    }\n    const payload = await request('PUT', `/api/v1/subscriptions/admin/${encodeURIComponent(username)}`, body)\n    const subscription = normalizeSubscription(payload.subscription || { ...patch, username })\n    subscriptionApi.hydrateSubscriptions?.({ [username]: subscription }, { merge: true })\n    return subscription\n  }\n\n  async function approveOrder(orderId) {\n    await request('POST', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/approve`)\n    await refreshOrders()\n    return { ok: true, order: orderState.find(order => order.id === String(orderId)) || null, message: '订阅申请已确认开通。' }\n  }\n\n  async function cancelOrder(orderId, options = {}) {\n    await request('POST', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/cancel`, {\n      note: String(options.note || '').trim(),\n    })\n    await refreshOrders()\n    const order = orderState.find(item => item.id === String(orderId)) || null\n    if (!order || order.status !== 'cancelled') throw new Error('订单取消后未能读取权威状态，请重试。')\n    return { ok: true, order, message: '订阅申请已取消。' }\n  }\n\n  async function generateRedeemCodes(options = {}) {\n    const payload = await request('POST', '/api/v1/subscriptions/redeem-codes/generate', {\n      planId: options.planId || 'monthly',\n      count: Math.max(1, Math.min(200, Number(options.count) || 1)),\n      prefix: String(options.prefix || 'VIP').trim(),\n      note: String(options.note || '').trim(),\n    })\n    const generated = new Set((payload.codes || []).map(code => String(code).toUpperCase()))\n    await refreshRedeemCodes()\n    const codes = redeemCodeState.filter(code => generated.has(code.code))\n    return { ok: true, codes, message: `已生成 ${codes.length} 张卡密。` }\n  }\n\n  async function updateRedeemCodeStatus(codeId, status) {\n    await request('PATCH', `/api/v1/subscriptions/redeem-codes/${encodeURIComponent(codeId)}`, { status })\n    await refreshRedeemCodes()\n    const code = redeemCodeState.find(item => item.id === String(codeId)) || null\n    if (!code || code.status !== status) throw new Error('卡密更新后未能读取权威状态，请重试。')\n    return { ok: true, code, message: status === 'disabled' ? '卡密已停用。' : '卡密已启用。' }\n  }\n\n  async function removeRedeemCode(codeId) {\n    await request('DELETE', `/api/v1/subscriptions/redeem-codes/${encodeURIComponent(codeId)}`)\n    await refreshRedeemCodes()\n    if (redeemCodeState.some(item => item.id === String(codeId))) {\n      throw new Error('卡密删除后仍存在，请重试。')\n    }\n    return { ok: true, message: '卡密已删除。' }\n  }\n\n  async function redeemCode(input) {\n    const payload = await request('POST', '/api/v1/subscriptions/redeem', { code: String(input || '').trim() })\n    const subscription = normalizeSubscription(payload.subscription || {})\n    if (subscription.username) subscriptionApi.hydrateSubscriptions?.({ [subscription.username]: subscription }, { merge: true })\n    return { ok: true, subscription, message: '卡密兑换成功，会员权益已更新。' }\n  }\n\n  async function retryInitialization() {\n    initialization = Object.freeze({ status: 'loading', error: null })\n    try {\n      const result = await refreshAuthenticatedContext()\n      initialization = Object.freeze({ status: 'ready', error: null })\n      return result\n    } catch (error) {\n      initialization = Object.freeze({ status: 'failed', error })\n      throw error\n    }\n  }\n\n  const domain = {\n    refreshRoleThemes,\n    refreshPlans,\n    refreshSubscription,\n    refreshAdminSettings,\n    refreshAdminLogs,\n    refreshOrders,\n    refreshRedeemCodes,\n    clearAdminLogs,\n    refreshAuthenticatedContext,\n    saveTheme,\n    resetTheme,\n    saveWechatConfig,\n    savePlan,\n    saveAllPlans,\n    setStudentSubscription,\n    retryInitialization,\n    initializationState: () => initialization,\n  }\n  domain.ready = retryInitialization()\n  global.KGSystemDomain = Object.freeze(domain)\n\n  global.KGWechatPay = Object.freeze({\n    createNativeOrder: planId => request('POST', '/api/v1/subscriptions/orders', { planId }),\n    getNativeOrderStatus: orderId => request('GET', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/status`),\n    cancelNativeOrder: orderId => request('POST', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/self-cancel`),\n    syncSubscription(subscription) {\n      const normalized = normalizeSubscription(subscription)\n      if (normalized.username) subscriptionApi.hydrateSubscriptions?.({ [normalized.username]: normalized }, { merge: true })\n      return normalized\n    },\n    nativeOrderQrCodeUrl: orderId => `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/qrcode`,\n  })\n\n  roleApi.saveTheme = saveTheme\n  roleApi.resetTheme = resetTheme\n  if (wechatApi) wechatApi.saveConfig = saveWechatConfig\n  subscriptionApi.setPlanSettings = savePlan\n  subscriptionApi.resetPlanSettings = planId => savePlan(planId, subscriptionApi.PLANS?.[planId] || {})\n  subscriptionApi.savePlanSettings = saveAllPlans\n  subscriptionApi.setStudentSubscription = setStudentSubscription\n  subscriptionApi.renewStudentSubscription = (username, planId, options = {}) => setStudentSubscription(username, {\n    planId, status: options.status || 'active', note: options.note || '',\n  })\n  subscriptionApi.pauseStudentSubscription = (username, note = '') => setStudentSubscription(username, { status: 'paused', note })\n  subscriptionApi.activateFreeSubscription = (username, note = '') => setStudentSubscription(username, { planId: 'free', status: 'active', note })\n  subscriptionApi.orderList = options => filteredRecords(orderState, options)\n    .slice().sort((left, right) => right.createdAt - left.createdAt)\n  subscriptionApi.pendingOrders = () => subscriptionApi.orderList({ status: 'pending' })\n  subscriptionApi.currentUserOrders = () => subscriptionApi.orderList({ username: userProfile?.username || '' })\n  subscriptionApi.hasPendingOrder = (username, planId) => subscriptionApi.orderList({ username, planId, status: 'pending' }).length > 0\n  subscriptionApi.approveOrder = approveOrder\n  subscriptionApi.cancelOrder = cancelOrder\n  subscriptionApi.redeemCodeList = options => filteredRecords(redeemCodeState, options)\n    .slice().sort((left, right) => right.createdAt - left.createdAt)\n  subscriptionApi.generateRedeemCodes = generateRedeemCodes\n  subscriptionApi.disableRedeemCode = codeId => updateRedeemCodeStatus(codeId, 'disabled')\n  subscriptionApi.enableRedeemCode = codeId => updateRedeemCodeStatus(codeId, 'unused')\n  subscriptionApi.removeRedeemCode = removeRedeemCode\n  subscriptionApi.redeemCode = redeemCode\n\n  if (typeof global.addEventListener === 'function') {\n    global.addEventListener('kg-auth-session-change', event => {\n      subscriptionRequest++\n      const username = String(event?.detail?.username || '').trim()\n      userProfile = null\n      if (!username) {\n        global.KGServerEntitlements = Object.freeze({ allExamPapers: false })\n        subscriptionApi.hydrateSubscriptions?.({})\n        return\n      }\n      refreshAuthenticatedContext().catch(error => console.error('[DirectSystemAdapter] auth refresh failed:', error))\n    })\n  }\n})(window)\n//# sourceURL=direct-system-adapter.js"],["src/33-user-center.js","\"use strict\";\n\n/*\n * 用户中心：当前登录用户自助维护个人资料。\n * 资料保存通过认证 API 完成，页面只使用认证核心的内存副本。\n */\n(function(){\n  const ACTIVE_PAID_MEMBERSHIP_STATUSES=new Set([\"active\",\"trial\",\"manual\"]);\n\n  const $=id=>document.getElementById(id);\n  const escapeHTML=window.KGAuthCore.escapeHTML;\n  const authCore=()=>window.KGAuthCore||null;\n  function makeSalt(){\n    const core=authCore();\n    return core&&typeof core.makeSalt===\"function\"?core.makeSalt():Math.random().toString(36).slice(2)+Date.now().toString(36);\n  }\n  function passwordHash(username,password,salt){\n    const core=authCore();\n    if(core&&typeof core.passwordHash===\"function\")return core.passwordHash(username,password,salt);\n    let h=2166136261;\n    const str=String(salt)+\"|\"+String(username).toLowerCase()+\"|\"+String(password);\n    for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h+=(h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24)}\n    return (h>>>0).toString(36);\n  }\n  function verifyPassword(username,password,user){\n    const core=authCore();\n    if(core&&typeof core.verifyPassword===\"function\")return core.verifyPassword(username,password,user);\n    return passwordHash(username,password,user&&user.salt||\"\")===(user&&user.hash);\n  }\n  function cleanUsername(value){\n    const core=authCore();\n    if(core&&typeof core.cleanUsername===\"function\")return core.cleanUsername(value);\n    return String(value||\"\").trim();\n  }\n  function cleanText(value,max=200){\n    return String(value||\"\").trim().slice(0,max);\n  }\n  function cleanSubject(value){\n    return cleanText(value,80)||\"PMP\";\n  }\n  function cleanTags(value){\n    return String(value||\"\")\n      .split(/[,，、;；|]/)\n      .map(s=>s.trim())\n      .filter(Boolean)\n      .slice(0,12);\n  }\n  function roleLabel(role){\n    const api=window.KGRolePermissions;\n    return api&&typeof api.roleLabel===\"function\"?api.roleLabel(role):({admin:\"管理员\",teacher:\"教师/教研\",student:\"学员\",viewer:\"游客\"}[role]||role||\"学员\");\n  }\n  function statusLabel(status){\n    return ({active:\"正常\",paused:\"暂停\",archived:\"已归档\"}[status]||status||\"正常\");\n  }\n  function subscriptionApi(){\n    return window.KGSubscription || null;\n  }\n  let nativePayPollTimer=0;\n  let subscriptionDetailGeneration=0;\n  function clearNativePayPolling(){\n    if(nativePayPollTimer){clearInterval(nativePayPollTimer);nativePayPollTimer=0;}\n  }\n  function setMembershipPaymentView(active){\n    const modal=document.querySelector(\"#userSubscriptionDetailModal .membership-ui\");\n    if(modal)modal.classList.toggle(\"is-payment-view\",!!active);\n  }\n  function renderSubscriptionBox(user){\n    const panel=$(\"ucSubscriptionBox\");\n    if(!panel)return;\n    panel.className=\"uc-info-card uc-membership-card\";\n    const sub=subscriptionApi();\n    if(!sub){\n      panel.innerHTML='<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-card-content\"><h3>订阅信息暂不可用</h3><p>请刷新页面后重试。</p></div>';\n      return;\n    }\n    const role=user&&user.role||\"student\";\n    if(role===\"admin\"||role===\"teacher\"){\n      panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>当前身份免订阅</h3><p>管理员和教师/教研不受学员订阅限制。</p></div></div><p class=\"uc-membership-note\">当前身份可直接使用系统管理或教学维护能力。</p></div>`;\n      return;\n    }\n    if(role===\"viewer\"){\n      panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>游客体验</h3><p>游客不进入订阅体系。</p></div></div><p class=\"uc-membership-note\">请登录或切换为学员账号后开通会员。</p></div>`;\n      return;\n    }\n    const summary=typeof sub.subscriptionSummary===\"function\"?sub.subscriptionSummary(user.username):null;\n    const plan=summary&&summary.plan || (sub.planById?sub.planById(\"free\"):{name:\"免费学员\"});\n    const record=summary&&summary.subscription || null;\n    const statusText=summary&&summary.statusText || \"有效\";\n    const expiresText=summary&&summary.expiresFullText || summary&&summary.expiresText || \"长期有效\";\n    const countdownText=summary&&summary.countdownText || \"长期有效\";\n    const hasActivePaidMembership=!!(record\n      && ACTIVE_PAID_MEMBERSHIP_STATUSES.has(record.status)\n      && plan\n      && plan.id\n      && plan.id!==\"free\");\n    const actionText=\"升级会员\";\n    panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div>\n      <div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>${escapeHTML(plan.name||\"免费学员\")}</h3><p>${escapeHTML(plan.description||\"当前学员订阅状态。\")}</p></div>${hasActivePaidMembership?\"\":`<button type=\"button\" class=\"uc-button uc-button-primary uc-button-compact\" id=\"ucSubscriptionRenewBtn\">${escapeHTML(actionText)}</button>`}</div>\n      <div class=\"uc-meta-chips\"><span>✓ 状态：${escapeHTML(statusText)}</span><span>▣ 有效期：${escapeHTML(expiresText)}</span><span>◷ 倒计时：${escapeHTML(countdownText)}</span><span>◇ 来源：${escapeHTML(summary&&summary.sourceText||\"其他来源\")}</span></div>\n      <p class=\"uc-membership-note\">此处展示当前订阅状态和权益有效期。</p></div>`;\n    const btn=$(\"ucSubscriptionRenewBtn\");\n    if(btn)btn.addEventListener(\"click\",openSubscriptionDetailModal);\n  }\n  function renderWechatBox(user){\n    const panel=$(\"ucWechatBox\");\n    if(!panel)return;\n    panel.className=\"uc-info-card uc-binding-card\";\n    const wechat=user&&user.wechat;\n    const bound=!!(wechat&&wechat.bound);\n    const nickname=String(wechat&&wechat.nickname||\"微信用户\");\n    panel.innerHTML=bound\n      ?`<div class=\"uc-card-icon uc-card-icon-wechat\">◉</div><div class=\"uc-card-content\"><h3>微信已绑定</h3><p>已绑定微信账号：${escapeHTML(nickname)}。以后可直接使用微信扫码登录。</p></div><button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucWechatUnbindBtn\">解除绑定</button>`\n      :`<div class=\"uc-card-icon uc-card-icon-wechat\">◉</div><div class=\"uc-card-content\"><h3>尚未绑定微信</h3><p>绑定后可使用微信扫码登录当前账号。</p></div><button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucWechatBindBtn\">绑定微信</button>`;\n    if(bound&&user.role==='student'){\n      const recover=document.createElement('button');\n      recover.type='button';recover.id='ucWechatRecoverBtn';recover.className='uc-button uc-button-outline uc-button-compact';\n      recover.textContent='找回原账号会员';\n      recover.onclick=()=>window.KGWechatLogin?.startOfficialLogin?.('recover');\n      panel.appendChild(recover);\n    }\n    const bind=$(\"ucWechatBindBtn\");\n    const unbind=$(\"ucWechatUnbindBtn\");\n    if(bind)bind.addEventListener(\"click\",()=>{\n      const api=window.KGWechatLogin;\n      if(!api||typeof api.startOfficialLogin!==\"function\"){msg(\"微信登录模块未加载，请刷新后重试。\");return}\n      msg(\"正在跳转至微信授权页…\",true);\n      api.startOfficialLogin('bind');\n    });\n    if(unbind)unbind.addEventListener(\"click\",async()=>{\n      const api=window.KGWechatLogin;\n      if(!api||typeof api.unbind!==\"function\"){msg(\"微信登录模块未加载，请刷新后重试。\");return}\n      if(!await window.KGDialogs.confirm(\"解除后将不能使用该微信扫码登录，确定解除绑定吗？\",{danger:true}))return;\n      unbind.disabled=true;\n      const result=await api.unbind();\n      if(!result||!result.ok){\n        unbind.disabled=false;\n        msg(result&&result.message||\"解除微信绑定失败。\");\n        return;\n      }\n      fillForm();\n      msg(\"微信绑定已解除。\",true);\n      showStatus(\"微信绑定已解除。\");\n    });\n  }\n  function planFeatureList(plan){\n    const sub=subscriptionApi();\n    if(sub&&typeof sub.planBenefitItems===\"function\")return sub.planBenefitItems(plan);\n    const labels=sub&&sub.FEATURE_LABELS||{};\n    return Object.entries(plan&&plan.features||{}).filter(([,on])=>!!on).map(([key])=>labels[key]||key);\n  }\n  function planLimitText(plan){\n    const sub=subscriptionApi();\n    if(sub&&typeof sub.planUsageText===\"function\")return sub.planUsageText(plan);\n    const labels={dailyTraining:\"每日训练\",recallMaps:\"回忆图谱\",importPackages:\"学习包导入\",exportPackages:\"学习包导出\"};\n    return Object.entries(plan&&plan.limits||{}).map(([key,value])=>`${labels[key]||key}：${Number(value)===-1?\"不限\":String(value)}`).join(\" · \");\n  }\n  function ensureSubscriptionDetailModal(){\n    let modal=$(\"userSubscriptionDetailModal\");\n    if(modal)return modal;\n    const wrap=document.createElement(\"div\");\n    wrap.className=\"modal-backdrop user-subscription-detail-backdrop membership-ui-backdrop\";\n    wrap.id=\"userSubscriptionDetailModal\";\n    wrap.innerHTML=`\n      <div aria-labelledby=\"userSubscriptionDetailTitle\" aria-modal=\"true\" class=\"modal kg-subscription-detail-modal membership-ui\" role=\"dialog\">\n        <header class=\"modal-header\">\n          <div class=\"brand\">\n            <div class=\"brand-mark\" aria-hidden=\"true\">会</div>\n            <div>\n              <h2 class=\"brand-title\" id=\"userSubscriptionDetailTitle\">会员权益</h2>\n              <p class=\"brand-copy\">查看各会员方案权益，选择套餐后可使用微信扫码开通。</p>\n            </div>\n          </div>\n          <button class=\"icon-button dialog-close\" id=\"userSubscriptionDetailCloseBtn\" type=\"button\" aria-label=\"关闭\"><span class=\"modal-close-icon\" aria-hidden=\"true\"></span></button>\n        </header>\n        <div class=\"kg-subscription-detail-body\" id=\"userSubscriptionDetailBody\"></div>\n      </div>`;\n    document.body.appendChild(wrap);\n    wrap.addEventListener(\"click\",event=>{if(event.target===wrap)closeSubscriptionDetailModal()});\n    $(\"userSubscriptionDetailCloseBtn\").addEventListener(\"click\",closeSubscriptionDetailModal);\n    return wrap;\n  }\n  function renderSubscriptionDetailPlans(){\n    setMembershipPaymentView(false);\n    const body=$(\"userSubscriptionDetailBody\");\n    const sub=subscriptionApi();\n    const rec=currentRecord();\n    if(!body||!sub){return}\n    clearNativePayPolling();\n    const detailGeneration=++subscriptionDetailGeneration;\n    const summary=rec&&typeof sub.subscriptionSummary===\"function\"?sub.subscriptionSummary(rec.username):null;\n    const currentPlanId=summary&&summary.plan&&summary.plan.id || \"\";\n    const currentPlanExpired=summary&&summary.subscription&&summary.subscription.status===\"expired\";\n    const plans=typeof sub.enabledPlanList===\"function\"?sub.enabledPlanList():[];\n    let activeNativeOrder=null;\n    let planPickLocked=false;\n    function setPlanPickLocked(locked){\n      planPickLocked=!!locked;\n      body.querySelectorAll('[data-buy-plan]').forEach(button=>{\n        const isActive=activeNativeOrder&&button.dataset.buyPlan===String(activeNativeOrder.planId||\"\");\n        button.disabled=planPickLocked&&!isActive;\n        button.setAttribute(\"aria-disabled\",String(planPickLocked&&!isActive));\n      });\n    }\n    body.innerHTML=`<div class=\"divider\"></div><div class=\"plans-grid\">\n      ${plans.map(plan=>{\n        // 历史套餐保留用于展示；到期后必须允许重新购买同套餐。\n        const current=!currentPlanExpired && !!currentPlanId && plan.id===currentPlanId;\n        const features=planFeatureList(plan);\n        const limitText=planLimitText(plan);\n        const featured=plan.id===\"monthly\"||!!plan.recommended;\n        const canPurchase=!current && plan.id!==\"free\";\n        const cta=current?(plan.id===\"free\"?\"当前使用中\":\"当前方案\"):(plan.id===\"free\"?\"免费使用\":\"选择该方案\");\n        return `<article class=\"plan-card${featured?' featured':''}${current?' current':''}\" data-plan-id=\"${escapeHTML(plan.id)}\">\n          <div class=\"plan-head\">\n            <h3 class=\"plan-title\">${escapeHTML(plan.name||'套餐')}</h3>\n            <span class=\"pill${plan.recommended&&!current?' pill-warning':''}\">${plan.recommended&&!current?'<span class=\"icon i-star\"></span>':''}${escapeHTML(current?'当前方案':(plan.badgeText||plan.shortName||'套餐'))}</span>\n          </div>\n          <div class=\"plan-price\">\n            <strong>${escapeHTML(plan.priceText||'待配置')}</strong>\n            ${plan.originalPriceText?`<del>${escapeHTML(plan.originalPriceText)}</del>`:''}\n          </div>\n          <p class=\"plan-desc\">${escapeHTML(plan.description||'')}</p>\n          <div class=\"plan-rule\"></div>\n          <div class=\"benefit-line\"><span class=\"benefit-dot\"></span><span>${escapeHTML(features[0]||'会员权益')}</span></div>\n          ${limitText?`<div class=\"feature-chip\"><span class=\"icon i-infinity\"></span><span>${escapeHTML(limitText)}</span></div>`:''}\n          <button type=\"button\" class=\"btn ${current?'current-btn':'btn-primary'}\"${canPurchase?` data-buy-plan=\"${escapeHTML(plan.id)}\"`:\" disabled\"}>${current?'<span class=\"icon i-check-circle\"></span>':''}${escapeHTML(cta)}${canPurchase?'<span class=\"icon i-chevron-right\"></span>':''}</button>\n        </article>`;\n      }).join('')}\n    </div>\n    <p class=\"redeem-message\" id=\"membershipPaymentMsg\" role=\"alert\" hidden></p>\n    <section class=\"membership-checkout\" id=\"membershipCheckout\" hidden aria-live=\"polite\"></section>\n    <section class=\"redeem\">\n      <div class=\"redeem-intro\">\n        <div class=\"redeem-icon\"><span class=\"icon i-ticket\"></span></div>\n        <div><h3 class=\"redeem-title\">卡密使用</h3><p class=\"redeem-copy\">使用会员卡密兑换会员权益</p></div>\n      </div>\n      <input class=\"redeem-input\" id=\"subscriptionRedeemCodeInput\" placeholder=\"请输入会员卡密，例如 VIP-XXXX-XXXX-XXXX\" autocomplete=\"off\" />\n      <button type=\"button\" class=\"btn btn-primary\" id=\"subscriptionRedeemCodeBtn\">兑换卡密</button>\n      <div class=\"redeem-message\" id=\"subscriptionRedeemCodeMsg\"></div>\n    </section>\n    <div class=\"footnote\"><span class=\"icon i-shield-check\"></span>卡密兑换成功后，权益将自动开通并即时生效</div>`;\n    function renderNativePayment(plan,order){\n      const pay=window.KGWechatPay;\n      if(!body||!pay||!order||!order.id)return;\n      clearNativePayPolling();\n      // 二维码已生成后解锁套餐按钮：点击其他套餐会重新下单（服务端自动作废旧\n      // 待支付订单），点击同一套餐则继续展示当前二维码。\n      setPlanPickLocked(false);\n      setMembershipPaymentView(true);\n      const amountFen=Math.max(0,Number(order.amount)||0);\n      const amount=`￥${amountFen%100===0?String(amountFen/100):(amountFen/100).toFixed(2)}`;\n      body.querySelectorAll(\".plan-card[data-plan-id]\").forEach(card=>card.classList.toggle(\"checkout-selected\",card.dataset.planId===String(plan&&plan.id||order.planId||\"\")));\n      const checkout=$(\"membershipCheckout\");\n      if(!checkout)return;\n      checkout.hidden=false;\n      checkout.innerHTML=`<div class=\"checkout-qr\"><div class=\"payment-tag\"><span class=\"icon i-wechat\"></span>微信扫码支付</div><div class=\"qr-frame\"><img class=\"kg-native-pay-qr\" src=\"${escapeHTML(pay.nativeOrderQrCodeUrl(order.id))}\" alt=\"微信支付二维码\" /></div></div>\n        <div class=\"checkout-summary\"><div><p class=\"summary-label\">正在开通</p><h3 class=\"checkout-plan-name\">${escapeHTML(plan&&plan.name||order.planName||'会员方案')}</h3><p class=\"checkout-help\">请使用微信扫描二维码完成付款，支付结果会自动刷新。</p></div><div class=\"checkout-amount\"><span>应付金额</span><strong>${escapeHTML(amount)}</strong></div><div class=\"checkout-meta\"><span>订单编号：${escapeHTML(order.id)}</span><span id=\"nativePayStatus\">等待扫码付款</span></div></div>\n        `;\n      const status=$(\"nativePayStatus\");\n      const refresh=async()=>{\n        try{\n          const latest=await pay.getNativeOrderStatus(order.id);\n          if(detailGeneration!==subscriptionDetailGeneration)return;\n          if(latest.payStatus===\"paid\"){\n            clearNativePayPolling();\n            pay.syncSubscription(latest.subscription);\n            renderOrderSubmitted(plan,{order});\n            showStatus(\"支付成功，会员权益已开通。\",true);\n            window.setTimeout(()=>{\n              closeSubscriptionDetailModal();\n              window.location.href=\"index.html?mode=free\";\n            },1600);\n            return;\n          }\n          if(status)status.textContent=\"等待扫码付款\";\n        }catch(error){\n          if(detailGeneration!==subscriptionDetailGeneration)return;\n          if(status)status.textContent=\"支付状态同步失败，正在自动重试\";\n        }\n      };\n      nativePayPollTimer=setInterval(refresh,3000);\n      refresh();\n    }\n    function renderOrderSubmitted(plan,result){\n      setMembershipPaymentView(false);\n      const order=result&&result.order||{};\n      body.innerHTML=`<div class=\"divider\"></div><section class=\"payment-success\"><div class=\"success-icon\"><span class=\"icon i-check-circle\"></span></div><h3>支付成功</h3><p>会员权益已开通，即将返回首页。</p><div class=\"success-meta\"><span>开通方案：${escapeHTML(plan&&plan.name||order.planName||'会员')}</span><span>订单编号：${escapeHTML(order.id||'—')}</span></div><button type=\"button\" class=\"btn btn-primary\" id=\"subscriptionCloseAfterSubmitBtn\">知道了</button></section>`;\n      $(\"subscriptionCloseAfterSubmitBtn\")?.addEventListener(\"click\",closeSubscriptionDetailModal);\n    }\n    function requestAuthenticationForPlan(plan){\n      closeSubscriptionDetailModal();\n      const reason=`登录后即可开通${plan&&plan.name||'会员方案'}。`;\n      showStatus(reason);\n      if(typeof window.authOpen===\"function\"){window.authOpen(reason);return}\n      $(\"authLoginBtn\")?.click();\n    }\n    async function handlePlanPick(card){\n      const planId=card&&card.dataset.buyPlan;\n      if(!planId)return;\n      const plan=sub.planById?sub.planById(planId):null;\n      if(planPickLocked)return; // 正在生成支付二维码，防止连点重复下单\n      if(activeNativeOrder&&activeNativeOrder.planId===planId){renderNativePayment(plan,activeNativeOrder);return}\n      const latest=currentRecord();\n      const role=latest&&latest.user&&latest.user.role || \"guest\";\n      if(!latest){\n        requestAuthenticationForPlan(plan);\n        return;\n      }\n      if(role===\"admin\"||role===\"teacher\"){\n        showStatus(\"当前身份不需要订阅，可直接使用管理或教学能力。\");\n        return;\n      }\n      if(role===\"viewer\"){\n        requestAuthenticationForPlan(plan);\n        return;\n      }\n      if(plan&&plan.id===\"free\"){\n        showStatus(\"免费学员无需购买，可直接使用免费权益。\");\n        return;\n      }\n      const pay=window.KGWechatPay;\n      if(!pay||typeof pay.createNativeOrder!==\"function\"){\n        showStatus(\"支付服务不可用，请刷新页面后重试。\");\n        return;\n      }\n      const originalLabel=card.innerHTML;\n      const paymentMsg=$(\"membershipPaymentMsg\");\n      if(paymentMsg){paymentMsg.textContent=\"\";paymentMsg.hidden=true;}\n      setPlanPickLocked(true);\n      card.textContent=\"正在生成支付二维码…\";\n      try{\n        if(activeNativeOrder&&activeNativeOrder.planId===plan.id){\n          card.innerHTML=originalLabel;\n          renderNativePayment(plan,activeNativeOrder);\n          return;\n        }\n        const result=await pay.createNativeOrder(plan.id);\n        if(detailGeneration!==subscriptionDetailGeneration)return;\n        if(!result||!result.order||!result.order.codeUrl)throw new Error(\"支付二维码生成失败，请重试。\");\n        // 服务端不复用待支付订单：每次点击都按当前所选套餐重新下单，\n        // 并自动作废旧待支付订单（点击哪个套餐就显示哪个套餐）。\n        const order=result.order;\n        const checkoutPlan=sub.planById?sub.planById(order.planId):null;\n        activeNativeOrder={...order,planId:order.planId||plan.id};\n        card.innerHTML=originalLabel;\n        renderNativePayment(checkoutPlan||plan,order);\n        showStatus(\"支付二维码已生成，请使用微信扫码。\");\n      }catch(error){\n        if(detailGeneration!==subscriptionDetailGeneration)return;\n        const message=String(error&&error.message||\"支付二维码生成失败，请重试。\");\n        if(paymentMsg){paymentMsg.textContent=message;paymentMsg.hidden=false;}\n        showStatus(message);\n        setPlanPickLocked(false);\n        card.innerHTML=originalLabel;\n      }\n    }\n    body.querySelectorAll('[data-buy-plan]').forEach(card=>card.addEventListener('click',()=>handlePlanPick(card)));\n    const redeemBtn=$(\"subscriptionRedeemCodeBtn\");\n    const redeemInput=$(\"subscriptionRedeemCodeInput\");\n    const redeemMsg=$(\"subscriptionRedeemCodeMsg\");\n    function setRedeemMsg(text,ok){\n      if(!redeemMsg)return;\n      redeemMsg.textContent=text||\"\";\n      redeemMsg.classList.toggle(\"ok\",!!ok);\n    }\n    if(redeemBtn&&redeemInput){\n      const submitRedeem=async()=>{\n        const api=subscriptionApi();\n        if(!api||typeof api.redeemCode!==\"function\"){setRedeemMsg(\"卡密模块未加载，请刷新页面后重试。\",false);return}\n        redeemBtn.disabled=true;\n        try{const result=await api.redeemCode(redeemInput.value);\n          setRedeemMsg(result&&result.message||\"卡密兑换失败。\",!!(result&&result.ok));\n          showStatus(result&&result.message||\"卡密兑换失败。\");\n          if(result&&result.ok){\n            redeemInput.value=\"\";\n            refreshAuthUI();\n            setTimeout(renderSubscriptionDetailPlans,600);\n          }\n        }catch(error){\n          const message=String(error&&error.message||\"卡密兑换失败，请重试。\");\n          setRedeemMsg(message,false);showStatus(message);\n        }finally{redeemBtn.disabled=false}\n      };\n      redeemBtn.addEventListener(\"click\",submitRedeem);\n      redeemInput.addEventListener(\"keydown\",event=>{\n        if(event.key===\"Enter\"){event.preventDefault();submitRedeem()}\n      });\n    }\n  }\n  function openSubscriptionDetailModal(){\n    const userCenter=$(\"userCenterModal\");\n    if(userCenter&&userCenter.classList.contains(\"show\"))userCenter.classList.remove(\"show\");\n    const modal=ensureSubscriptionDetailModal();\n    setMembershipPaymentView(false);\n    renderSubscriptionDetailPlans();\n    modal.classList.add(\"show\");\n  }\n  function closeSubscriptionDetailModal(){\n    subscriptionDetailGeneration++;\n    clearNativePayPolling();\n    setMembershipPaymentView(false);\n    const modal=$(\"userSubscriptionDetailModal\");\n    if(modal)modal.classList.remove(\"show\");\n  }\n\n  function currentUsername(){\n    const core=authCore();\n    return core&&typeof core.currentUsername===\"function\"?core.currentUsername():\"\";\n  }\n  function users(){\n    const core=authCore();\n    return core&&typeof core.users===\"function\"?core.users():{};\n  }\n  function saveUser(username,patch){\n    const core=authCore();\n    if(core&&typeof core.upsertUser===\"function\")return core.upsertUser(username,patch);\n    return null;\n  }\n  function currentRecord(){\n    const username=currentUsername();\n    if(!username)return null;\n    const core=authCore();\n    const coreUser=core&&typeof core.currentUser===\"function\"?core.currentUser({includeInactive:true}):null;\n    if(coreUser)return {username,user:{...coreUser}};\n    const map=users();\n    const user=map[username];\n    if(!user||typeof user!==\"object\")return null;\n    return {username,user:{...user}};\n  }\n  function logAction(action,username,detail=\"\"){\n    const core=authCore();\n    if(core&&typeof core.logAction===\"function\")return core.logAction(action,username,detail);\n    return null;\n  }\n  function showStatus(message){\n    if(typeof window.showStatus===\"function\")window.showStatus(message);\n    else{\n      const status=$(\"status\");\n      if(status){\n        status.textContent=message;\n        status.classList.add(\"show\");\n        clearTimeout(showStatus.timer);\n        showStatus.timer=setTimeout(()=>status.classList.remove(\"show\"),2200);\n      }\n    }\n  }\n  function refreshAuthUI(){\n    const api=window.KGRolePermissions;\n    if(api){\n      if(typeof api.applyTheme===\"function\")api.applyTheme();\n      const status=$(\"authStatus\");\n      if(status&&typeof api.renderStatus===\"function\")api.renderStatus(status);\n      if(typeof api.decoratePermissionElements===\"function\")api.decoratePermissionElements();\n    }\n    if(typeof window.authRenderStatus===\"function\")window.authRenderStatus();\n    if(window.KGSubscription&&typeof window.KGSubscription.decorateSubscriptionElements===\"function\")window.KGSubscription.decorateSubscriptionElements();\n    if(window.KGGlobalShortcuts&&typeof window.KGGlobalShortcuts.render===\"function\")window.KGGlobalShortcuts.render();\n    window.dispatchEvent(new CustomEvent(\"kg-user-profile-updated\",{detail:{username:currentUsername()}}));\n    window.dispatchEvent(new CustomEvent(\"kg-role-theme-change\",{detail:{role:api&&api.currentRole?api.currentRole():\"\"}}));\n  }\n  let referralRequest=0;\n  async function renderReferralBox(user,{create=false}={}){\n    const panel=$('ucReferralBox'),owner=currentUsername(),request=++referralRequest;\n    if(!panel||!owner)return;\n    const heading='<div class=\"uc-card-icon uc-card-icon-membership\" aria-hidden=\"true\">♧</div><div class=\"uc-card-content\"><h3>我的推荐码</h3><p>好友首次付费后，双方各得 7 天会员。注册仅绑定推荐关系；未到期会员顺延，永久会员权益保持不变。</p>';\n    panel.innerHTML=heading+'<p role=\"status\">正在读取推荐信息…</p></div>';\n    const isCurrent=()=>request===referralRequest&&owner===currentUsername();\n    try{\n      if(typeof authCore()?.referralSummary!=='function')throw new Error('推荐信息暂不可用');\n      const [result]=await Promise.all([authCore().referralSummary({create}),(async()=>{\n        const refresh=window.KGSystemDomain?.refreshSubscription;\n        if(typeof refresh!=='function')return;\n        await refresh();\n        if(isCurrent()){renderSubscriptionBox(user);subscriptionApi()?.decorateSubscriptionElements?.()}\n      })()]);\n      if(!isCurrent())return;\n      const code=String(result.code||''),count=Math.max(0,Math.floor(Number(result.registeredCount)||0)),rewarded=Math.max(0,Math.floor(Number(result.rewardedCount)||0));\n      if(code&&!/^[A-F0-9]{16}$/.test(code))throw new Error('推荐信息读取失败，请重试');\n      let fields='';\n      if(code){\n        const link=new URL('/practice-mode.html',window.location.href);link.searchParams.set('referralCode',code);\n        fields='<label class=\"uc-field\"><span>我的推荐码</span><div><input id=\"ucReferralCode\" readonly value=\"'+escapeHTML(code)+'\"/></div></label>'+\n          '<button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" data-referral-copy=\"ucReferralCode\">复制推荐码</button>'+\n          '<label class=\"uc-field\"><span>推荐注册链接</span><div><input id=\"ucReferralLink\" readonly value=\"'+escapeHTML(link.href)+'\"/></div></label>'+\n          '<button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" data-referral-copy=\"ucReferralLink\">复制推荐链接</button>';\n      }else fields='<button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucReferralGenerate\">获取推荐码</button>';\n      panel.innerHTML=heading+'<p>通过我的推荐码已注册 '+count+' 人 · 已完成奖励 '+rewarded+' 人</p><div class=\"uc-referral-fields\">'+fields+'</div>'+'<p role=\"status\" id=\"ucReferralStatus\"></p></div>';\n      $('ucReferralGenerate')?.addEventListener('click',()=>{if(isCurrent())void renderReferralBox(user,{create:true})});\n      panel.querySelectorAll('[data-referral-copy]').forEach(button=>button.addEventListener('click',async()=>{\n        if(!isCurrent())return;\n        const input=$(button.dataset.referralCopy),value=input?.value;if(!value)return;\n        try{\n          if(!navigator.clipboard?.writeText)throw new Error('clipboard unavailable');\n          await navigator.clipboard.writeText(value);\n          if(isCurrent())$('ucReferralStatus').textContent='已复制';\n        }catch(_){if(isCurrent()){input.focus();input.select();$('ucReferralStatus').textContent='复制未完成，已选中内容，可手动复制。'}}\n      }));\n    }catch(error){\n      if(!isCurrent())return;\n      panel.innerHTML=heading+'<p role=\"status\">推荐及会员信息读取失败，请重试。</p><button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucReferralRetry\">重试</button></div>';\n      $('ucReferralRetry')?.addEventListener('click',()=>{if(isCurrent())void renderReferralBox(user,{create})});\n    }\n  }\n  function ensureModal(){\n    let modal=$(\"userCenterModal\");\n    if(modal)return modal;\n    const wrap=document.createElement(\"div\");\n    wrap.className=\"modal-backdrop user-center-backdrop\";\n    wrap.id=\"userCenterModal\";\n    wrap.innerHTML=`\n      <div aria-labelledby=\"userCenterTitle\" aria-modal=\"true\" class=\"modal kg-user-center-modal uc-dialog\" role=\"dialog\">\n        <header class=\"uc-header\"><div class=\"uc-profile-heading\"><div class=\"uc-avatar\" id=\"userCenterAvatar\">我</div><div><h2 id=\"userCenterTitle\">用户中心</h2><p>维护自己的账号资料。角色和账号状态由管理员统一调整。</p></div></div><button class=\"uc-close dialog-close\" id=\"userCenterCloseBtn\" type=\"button\" aria-label=\"关闭用户中心\"><span class=\"modal-close-icon\" aria-hidden=\"true\"></span></button></header>\n        <div class=\"kg-user-center-body uc-body\"><div class=\"uc-form-grid\">\n          <label class=\"uc-field uc-field-readonly\"><span>用户名</span><div><input id=\"ucUsername\" readonly /><b aria-hidden=\"true\">♙</b></div></label>\n          <label class=\"uc-field\"><span>显示名称</span><div><input id=\"ucDisplayName\" maxlength=\"40\" placeholder=\"例如：Alex / 张老师\" /></div></label>\n          <label class=\"uc-field\"><span>邮箱</span><div><input id=\"ucEmail\" maxlength=\"120\" placeholder=\"name@example.com\" /></div></label>\n          <label class=\"uc-field\"><span>手机 / 联系方式</span><div><input id=\"ucPhone\" maxlength=\"40\" placeholder=\"可选\" /></div></label>\n          <label class=\"uc-field\"><span>主要科目</span><div><input id=\"ucSubject\" maxlength=\"80\" placeholder=\"PMP / ACP / CSPM\" /></div></label>\n          <label class=\"uc-field\"><span>标签</span><div><input id=\"ucTags\" maxlength=\"160\" placeholder=\"多个标签用逗号分隔\" /></div></label>\n        </div>\n        <div class=\"uc-status-row\"><span class=\"uc-status-chip uc-role\" id=\"ucRoleChip\">角色：—</span><span class=\"uc-status-chip uc-normal\" id=\"ucStatusChip\">状态：—</span></div>\n        <section class=\"uc-info-card uc-binding-card\" id=\"ucWechatBox\" aria-label=\"微信登录\"></section>\n        <section class=\"uc-info-card uc-membership-card\" id=\"ucSubscriptionBox\" aria-label=\"我的订阅\"></section>\n        <section class=\"uc-info-card uc-binding-card uc-referral-card\" id=\"ucReferralBox\" aria-label=\"我的推荐码\"></section>\n        <label class=\"uc-field uc-notes-field\"><span>个人备注 / 学习说明</span><div class=\"uc-textarea-wrap\"><textarea id=\"ucNote\" maxlength=\"500\" placeholder=\"例如：所在班级、学习目标、备考进度等，保存后会同步到服务器。\"></textarea><em id=\"ucNoteCount\">0/500</em></div></label>\n        <section class=\"uc-password-card\"><h3>安全设置 · 修改密码（可选）</h3><p id=\"ucPasswordHelp\">不修改密码时请留空。已有密码须填写当前密码；首次设置须在微信登录后 10 分钟内完成。</p><div class=\"uc-form-grid uc-password-grid\"><label class=\"uc-field\"><span>当前密码</span><div><input id=\"ucCurrentPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"修改密码时填写\" /></div></label><label class=\"uc-field\"><span>新密码</span><div><input id=\"ucNewPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"至少 4 位\" /></div></label><label class=\"uc-field\"><span>确认新密码</span><div><input id=\"ucConfirmPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"再次输入新密码\" /></div></label></div></section>\n        </div>\n        <footer class=\"kg-user-center-footer\" data-uc-footer><div class=\"kg-user-center-msg uc-message\" id=\"userCenterMsg\"></div><div class=\"uc-actions\"><button class=\"uc-button uc-button-secondary\" id=\"userCenterCancelBtn\" type=\"button\">取消</button><button class=\"uc-button uc-button-primary\" id=\"userCenterSaveBtn\" type=\"button\">保存个人资料</button></div></footer>\n      </div>`;\n    document.body.appendChild(wrap);\n    wrap.addEventListener(\"click\",event=>{if(event.target===wrap)closeModal()});\n    $(\"userCenterCloseBtn\").addEventListener(\"click\",closeModal);\n    $(\"userCenterCancelBtn\").addEventListener(\"click\",closeModal);\n    $(\"userCenterSaveBtn\").addEventListener(\"click\",saveProfile);\n    $(\"ucNote\").addEventListener(\"input\",()=>{\n      const count=$(\"ucNoteCount\");\n      if(count)count.textContent=`${$(\"ucNote\").value.length}/500`;\n    });\n    document.addEventListener(\"keydown\",event=>{\n      if(event.key===\"Escape\"){\n        if($(\"userSubscriptionDetailModal\")&&$(\"userSubscriptionDetailModal\").classList.contains(\"show\"))closeSubscriptionDetailModal();\n        else if(wrap.classList.contains(\"show\"))closeModal();\n      }\n    });\n    return wrap;\n  }\n  function msg(text,ok=false){\n    const el=$(\"userCenterMsg\");\n    if(!el)return;\n    el.textContent=text||\"\";\n    el.classList.toggle(\"ok\",!!ok);\n  }\n  function fillForm(){\n    const rec=currentRecord();\n    if(!rec)return false;\n    const {username,user}=rec;\n    $(\"ucUsername\").value=username;\n    $(\"ucDisplayName\").value=user.displayName||username;\n    $(\"ucEmail\").value=user.email||\"\";\n    $(\"ucPhone\").value=user.phone||\"\";\n    $(\"ucSubject\").value=user.subject||\"PMP\";\n    $(\"ucTags\").value=Array.isArray(user.tags)?user.tags.join(\"，\"):String(user.tags||\"\");\n    $(\"ucNote\").value=user.note||\"\";\n    $(\"ucNoteCount\").textContent=`${$(\"ucNote\").value.length}/500`;\n    $(\"ucRoleChip\").textContent=\"角色：\"+roleLabel(user.role||\"student\");\n    $(\"ucStatusChip\").textContent=\"状态：\"+statusLabel(user.status||\"active\");\n    renderWechatBox(user);\n    renderSubscriptionBox(user);\n    void renderReferralBox(user);\n    const firstPassword=user.has_password===false;\n    $(\"ucCurrentPassword\").closest(\"label\").hidden=firstPassword;\n    $(\"ucPasswordHelp\").textContent=firstPassword\n      ?\"首次设置密码：请在微信登录后 10 分钟内完成，无需当前密码。若提示认证过期，请关闭用户中心、退出后重新微信登录。请记下上方用户名，手机网页登录时使用。\"\n      :\"不修改密码时请留空；修改密码必须填写当前密码。\";\n    $(\"ucCurrentPassword\").value=\"\";\n    $(\"ucNewPassword\").value=\"\";\n    $(\"ucConfirmPassword\").value=\"\";\n    const avatar=$(\"userCenterAvatar\");\n    const name=String(user.displayName||username||\"我\").trim();\n    avatar.textContent=name.slice(0,1).toUpperCase()||\"我\";\n    msg(\"\");\n    return true;\n  }\n  function openModal(){\n    const modal=ensureModal();\n    const rec=currentRecord();\n    if(!rec){\n      const login=$(\"authLoginBtn\");\n      if(login){\n        login.click();\n        showStatus(\"请先登录后再进入用户中心。\");\n      }else{\n        void window.KGDialogs.alert(\"请先登录后再进入用户中心。\");\n      }\n      return;\n    }\n    if(!fillForm())return;\n    modal.classList.add(\"show\");\n    setTimeout(()=>$(\"ucDisplayName\")&&$(\"ucDisplayName\").focus(),80);\n  }\n  function closeModal(){\n    referralRequest++;\n    const modal=$(\"userCenterModal\");\n    if(modal)modal.classList.remove(\"show\");\n  }\n  async function saveProfile(){\n    const rec=currentRecord();\n    if(!rec){msg(\"请先登录。\");return}\n    const {username,user}=rec;\n    const displayName=cleanText($(\"ucDisplayName\").value,40)||username;\n    const email=cleanText($(\"ucEmail\").value,120);\n    const phone=cleanText($(\"ucPhone\").value,40);\n    const subject=cleanSubject($(\"ucSubject\").value);\n    const tags=cleanTags($(\"ucTags\").value);\n    const note=cleanText($(\"ucNote\").value,500);\n    const currentPassword=String($(\"ucCurrentPassword\").value||\"\");\n    const newPassword=String($(\"ucNewPassword\").value||\"\");\n    const confirmPassword=String($(\"ucConfirmPassword\").value||\"\");\n\n    if(email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)){\n      msg(\"邮箱格式不正确。\");\n      return;\n    }\n    if(newPassword||confirmPassword||currentPassword){\n      if(newPassword.length<4){\n        msg(\"新密码至少 4 位。\");\n        return;\n      }\n      if(newPassword!==confirmPassword){\n        msg(\"两次输入的新密码不一致。\");\n        return;\n      }\n      if(!authCore()?.providerStatus?.().remote&&user.hash){\n        const ok=verifyPassword(username,currentPassword,user);\n        if(!ok){\n          msg(\"当前密码不正确。\");\n          return;\n        }\n      }\n      if(!authCore()?.providerStatus?.().remote){\n        const salt=makeSalt();\n        user.salt=salt;\n        user.hash=passwordHash(username,newPassword,salt);\n      }\n    }\n\n    const patch={\n      ...user,\n      displayName,\n      email,\n      phone,\n      subject,\n      tags,\n      note,\n      updatedAt:Date.now()\n    };\n    const core=authCore();\n    const saveBtn=$(\"userCenterSaveBtn\");if(saveBtn)saveBtn.disabled=true;\n    try{\n      if(core?.providerStatus?.().remote&&typeof core.updateProfile===\"function\"){\n        const result=await core.updateProfile({...patch,currentPassword,newPassword});\n        if(!result?.ok){msg(result?.message||\"个人资料保存失败，请稍后重试。\");return}\n      }else saveUser(username,patch);\n    }finally{if(saveBtn)saveBtn.disabled=false}\n    logAction(\"用户自助更新资料\",username,newPassword?\"更新资料并修改密码\":\"更新资料\");\n    refreshAuthUI();\n    fillForm();\n    msg(\"个人资料已保存。\",true);\n    showStatus(\"个人资料已更新。\");\n    setTimeout(closeModal,650);\n  }\n  function bindEntry(){\n    const status=$(\"authStatus\");\n    if(!status)return;\n    if(String(status.dataset.accountMenuTrigger||\"\").toLowerCase()===\"true\"){\n      // 首页账号胶囊由 KGAccountMenu 统一接管；避免点击后直接弹出用户中心。\n      status.dataset.userCenterEntry=\"account-menu\";\n      return;\n    }\n    if(status.dataset.userCenterBound===\"1\")return;\n    status.dataset.userCenterBound=\"1\";\n    status.setAttribute(\"role\",\"button\");\n    status.setAttribute(\"tabindex\",\"0\");\n    status.setAttribute(\"title\",\"点击打开用户中心\");\n    status.addEventListener(\"click\",event=>{\n      event.preventDefault();\n      openModal();\n    });\n    status.addEventListener(\"keydown\",event=>{\n      if(event.key===\"Enter\"||event.key===\" \"){\n        event.preventDefault();\n        openModal();\n      }\n    });\n  }\n  function bindSubscriptionEntrypoints(){\n    document.querySelectorAll(\"#upgradeMemberBtn,[data-open-subscription-detail]\").forEach(btn=>{\n      if(!btn || btn.dataset.subscriptionDetailBound===\"1\")return;\n      btn.dataset.subscriptionDetailBound=\"1\";\n      btn.addEventListener(\"click\",event=>{\n        event.preventDefault();\n        openSubscriptionDetailModal();\n      });\n    });\n  }\n  function init(){\n    bindEntry();\n    bindSubscriptionEntrypoints();\n    ensureModal();\n    window.addEventListener('kg-auth-session-change',()=>{\n      referralRequest++;\n      const panel=$('ucReferralBox');if(panel)panel.replaceChildren();\n      if($('userCenterModal')?.classList.contains('show')){\n        if(currentRecord())fillForm();else closeModal();\n      }\n    });\n    window.addEventListener(\"kg-user-profile-updated\",()=>setTimeout(()=>{bindEntry();bindSubscriptionEntrypoints()},0));\n    window.addEventListener(\"kg-subscription-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    window.addEventListener(\"kg-subscription-plan-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    window.addEventListener(\"kg-wechat-binding-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    // 远程套餐价格异步到达时重绘已打开的会员权益弹窗：修复首次打开显示内置\n    // 兜底价（￥29）、再次打开才显示后台配置价的竞态（弹窗此前不监听该事件）。\n    window.addEventListener(\"kg-subscription-plan-change\",()=>{\n      if($(\"userSubscriptionDetailModal\")&&$(\"userSubscriptionDetailModal\").classList.contains(\"show\"))renderSubscriptionDetailPlans();\n    });\n  }\n  if(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",init);\n  else init();\n  window.KGUserCenter={open:openModal,refresh:refreshAuthUI,openSubscriptionDetail:openSubscriptionDetailModal,closeSubscriptionDetail:closeSubscriptionDetailModal};\n})();\n//# sourceURL=src/33-user-center.js"]]);
